GimCorpus.put(109,0,[[1,1,"וּבִשְׁנַת אַחַת לְכוֹרֶשׁ מֶלֶךְ פָּרַס. סֵדֶר סֵפֶר זֶה סָדוּר וּמָשׁוּךְ אַחַר סֵפֶר דָּנִיֵּאל כַּמְפֹרָשׁ בְּבָבָא בַּתְרָא (בבא בתרא טו.), וְהַמִּלָּה מוּסֶבֶת מִזֶּה לָזֶה שֶׁנֶּאֱמַר בְּדָנִיֵּאל בִּשְׁנַת אַחַת לְמָלְכוֹ ״אֲנִי דָנִיֵּאל בִּינֹתִי בַּסְּפָרִים מִסְפַּר הַשָּׁנִים אֲשֶׁר הָיָה דְבַר ה׳ אֶל יִרְמְיָה הַנָּבִיא לְמַלֹּאות לְחָרְבוֹת יְרוּשָׁלַיִם שִׁבְעִים שָׁנָה״ (דניאל ט:ב), וְכֵן הוֹלֶכֶת וּמְסַפֶּרֶת כָּל הַפָּרָשָׁה בְּחֻרְבַּן הַבַּיִת וּזְמַן גָּלוּת בָּבֶל וְאֶת וִדּוּיוֹ אֲשֶׁר הִתְוַדָּה עַל חַטַּאת יִשְׂרָאֵל. וּתְחִלַּת סֵדֶר סֵפֶר זֶה כָּךְ הוּא, שֶׁלְּאַחַר שֶׁנֶּהֱרַג בֵּלְשַׁצַּר מָלַךְ דָּרְיָוֶשׁ הַמָּדִי שֶׁנֶּאֱמַר ״וְדָרְיָוֶשׁ מָדָאָה קַבֵּל מַלְכוּתָא וְגוֹמֵר״ (דניאל ו:א), וּלְאַחַר מִיתַת דָּרְיָוֶשׁ מָלַךְ כּוֹרֶשׁ זֶה מֶלֶךְ פָּרַס, וּבִשְׁנַת אַחַת לְמָלְכוֹ הֻשְׁלְמוּ שִׁבְעִים שָׁנָה לִפְקִידַת גָּלוּת בָּבֶל מִיּוֹם שֶׁגָּלָה יְהוֹיָקִים שֶׁנֶּאֱמַר ״לְפִי מְלֹאת לְבָבֶל שִׁבְעִים שָׁנָה אֶפְקֹד אֶתְכֶם וְגוֹ׳״ (ירמיהו כט:י), שֶׁחָזְרוּ יִשְׂרָאֵל מִגָּלוּת בָּבֶל לְאֶרֶץ יִשְׂרָאֵל וּבְאוֹתָהּ שָׁנָה בִּשְׁנַת אַחַת לְכוֹרֶשׁ יָסְדוּ יִשְׂרָאֵל יְסוֹד בֵּית הַמִּקְדָּשׁ, וְצָרֵי יְהוּדָה וּבִנְיָמִין הִלְשִׁינוּ עֲלֵיהֶם לְכוֹרֶשׁ מֶלֶךְ פָּרַס וְצִוָּה לְבַטֵּל הַמְּלָאכָה, שֶׁלֹּא לִבְנוֹת עוֹד בִּנְיַן בֵּית הַמִּקְדָּשׁ וְהָיוּ יִשְׂרָאֵל בְּטֵלִים שֶׁלֹּא בָנוּ הַבַּיִת כָּל מַלְכוּת כּוֹרֶשׁ וַאֲחַשְׁוֵרוֹשׁ שֶׁמָּלַךְ אַחֲרָיו עַד שְׁנַת שְׁתַּיִם לְמַלְכוּת דָּרְיָוֶשׁ בֶּן אֲחַשְׁוֵרוֹשׁ מֶלֶךְ פָּרַס, שֶׁהוּא דָּרְיָוֶשׁ בֶּן אֶסְתֵּר, וּבִשְׁנַת שְׁתַּיִם לְמַלְכוּתוֹ הִתְחִילוּ לִבְנוֹת בֵּית הַמִּקְדָּשׁ עַד אֲשֶׁר הֻשְׁלַם הַבִּנְיָן, וּמִשְּׁנַת אַחַת לְכוֹרֶשׁ עַד שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ בֶּן אֲחַשְׁוֵרוֹשׁ מֶלֶךְ פָּרַס שֶׁנִּבְנָה הַבַּיִת בְּיָמָיו הָיוּ שְׁמוֹנֶה עֶשְׂרֵה שָׁנָה, לְקַיֵּם מַה שֶּׁנֶּאֱמַר ״לְמַלֹּאות לְחָרְבוֹת יְרוּשָׁלַיִם שִׁבְעִים שָׁנָה וְגוֹ׳״ (דניאל ט:ב), וְעַכְשָׁיו בִּשְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ הֻשְׁלְמוּ שִׁבְעִים שָׁנָה לְמַלֹּאות לְחָרְבוֹת יְרוּשָׁלַיִם חֻרְבַּן הַבַּיִת שֶׁגָּלָה צִדְקִיָּהוּ. וּמִגָּלוּת יְהוֹיָקִים עַד גָּלוּת צִדְקִיָּהוּ שֶׁנֶּחֱרַב הַבַּיִת הָיוּ שְׁמֹנֶה עֶשְׂרֵה שָׁנָה, וְעַכְשָׁיו בִּשְׁנַת אַחַת לְכוֹרֶשׁ מֶלֶךְ פָּרַס הֻשְׁלְמוּ שִׁבְעִים שָׁנָה מִגָּלוּת יְהוֹיָקִים שֶׁגָּלוּ יִשְׂרָאֵל לְבָבֶל, וּבְכָךְ נִתְקַיֵּם הַמִּקְרָא שֶׁנֶּאֱמַר ״כִּי לְפִי מְלֹאת לְבָבֶל שִׁבְעִים שָׁנָה אֶפְקֹד אֶתְכֶם וְגוֹמֵר״ (ירמיהו כט:י), וְזוֹ הִיא הַפְּקִידָה שֶׁחָזְרוּ יִשְׂרָאֵל עַל אַדְמָתָם וּבָנוּ יְסוֹד בִּנְיַן הַבַּיִת אַף עַל פִּי שֶׁלֹּא נִגְמַר עַכְשָׁיו. נִמְצָא שֶׁהָיָה חֲמִשִּׁים וּשְׁתַיִם שָׁנָה מִגָּלוּת צִדְקִיָּהוּ שֶׁנֶּחֱרַב הַבַּיִת עַד שָׁנָה אַחַת לְכוֹרֶשׁ מֶלֶךְ פָּרַס, וּשְׁמֹנֶה עֶשְׂרֵה לְאַחַר שָׁנָה אַחַת לְכוֹרֶשׁ שֶׁהִיא שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ מֶלֶךְ פָּרַס, הֻשְׁלְמוּ שִׁבְעִים שָׁנָה לְחָרְבוֹת יְרוּשָׁלַיִם מִגָּלוּת צִדְקִיָּהוּ שֶׁנֶּחֱרַב הַבַּיִת עַד שְׁתַּיִם לְדָרְיָוֶשׁ שֶׁהִתְחִילוּ יִשְׂרָאֵל לִבְנוֹת הַבִּנְיָן וּגְמָרוּהוּ. וְכֵן מוֹכִיחַ בְּסֵדֶר עוֹלָם (פרק כט) וּבִמְסֶכֶת מְגִלָּה (מגילה יא:) וּבְסֵפֶר זֶה כַּאֲשֶׁר בֵּאַרְתִּי:",1,0],[1,1,"לִכְלוֹת דְּבַר ה׳ מִפִּי יִרְמְיָה. לִזְמַן אֲשֶׁר הֻשְׁלַם דְּבָרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר דִּבֵּר יִרְמְיָהוּ הַנָּבִיא, שֶׁנֶּאֱמַר (ירמיהו כט:י): ״כִּי לְפִי מְלֹאת לְבָבֶל וְגוֹ׳״:",2,0],[1,1,"הֵעִיר ה׳ אֶת רוּחַ. רָצוֹן:",3,0],[1,1,"קוֹל. כָּרוֹז הִכְרִיז בְּכָל מַלְכוּתוֹ:",4,0],[1,1,"וְגַם בְּמִכְתָּב. וְאַף מִכְתָּבוֹ שָׁלַח בְּכָל מַלְכוּתוֹ עַל דָּבָר זֶה:",5,0],[1,1,"לֵאמֹר. וְכֹה אָמַר לָהֶם בְּהַכְרֵז הַכָּרוֹז אֲשֶׁר הִכְרִיז וּבְאִגֶּרֶת מִכְתָּבוֹ אֲשֶׁר שָׁלַח בְּכָל מַלְכוּתוֹ:",6,0],[1,2,"כֹּה אָמַר כּוֹרֶשׁ מֶלֶךְ פָּרַס וְגוֹ׳ נָתַן לִי. שֶׁאֲנִי מֶלֶךְ וְשַׁלִּיט עַל כָּל הַמַּמְלָכוֹת:",1,0],[1,2,"וְהוּא פָקַד עָלַי. צִוָּה עָלַי עַל יְדֵי יְשַׁעְיָה הַנָּבִיא לִבְנוֹת לוֹ בֵּית הַמִּקְדָּשׁ בִּירוּשָׁלַיִם, כְּמוֹ שֶׁנֶּאֱמַר בְּסֵפֶר יְשַׁעְיָה (ישעיה מד:כח): ״הָאוֹמֵר לְכוֹרֶשׁ רֹעִי וְכָל חֶפְצִי יַשְׁלִים וְלֵאמֹר לִירוּשָׁלַיִם תִּבָּנֶה וְהֵיכָל תִּוָּסֵד״ (ישעיה מה:א), ״כֹּה אָמַר ה׳ לִמְשִׁיחוֹ לְכוֹרֶשׁ אֲשֶׁר הֶחֱזַקְתִּי בִימִינוֹ וְגוֹמֵר״. וּכְבָר נֶאֶמְרָה נְבוּאָה זוֹ עַל יְדֵי יְשַׁעְיָה:",2,0],[1,2,"בִּירוּשָׁלִַם אֲשֶׁר בִּיהוּדָה. אֲשֶׁר בִּמְדִינַת יְהוּדָה:",3,0],[1,3,"מִי בָכֶם. כָּךְ הָיָה מַכְרִיז וְכוֹתֵב לְכָל הַמַּמְלָכוֹת: מִי בָכֶם מִכָּל עַמּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, יְהִי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעֶזְרוֹ, וְיַעֲלֶה לִבְנוֹת בֵּיתוֹ אֲשֶׁר בִּירוּשָׁלַיִם:",1,0],[1,4,"וְכָל הַנִּשְׁאָר. וְכָל יְהוּדִי הַנִּשְׁאָר בִּמְקוֹמוֹ שֶׁלֹּא יוּכַל לַעֲלוֹת מֵחֲמַת שֶׁאֵין לוֹ מָמוֹן:",1,0],[1,4,"יְנַשְּׂאוּהוּ. מְצַוֶּה אֲנִי לְאַנְשֵׁי מְקוֹמוֹ שֶׁיַּעֲנִיקוּהוּ וִינַשְּׂאוּהוּ בְּכֶסֶף וּבְזָהָב וּרְכוּשׁ וּבְהֵמוֹת לְמַעַן יוּכַל לַעֲלוֹת לִירוּשָׁלַיִם עִם הַנְּדָבָה אֲשֶׁר יִתְנַדְּבוּ אַנְשֵׁי מְקוֹמוֹ לְבִנְיַן הַבַּיִת, שֶׁאַף הָאֻמּוֹת יֵשׁ בָּהֶם אֲשֶׁר הָיוּ מִתְנַדְּבִים נְדָבָה לְבִנְיַן הַבַּיִת:",2,0],[1,4,"לְבֵית הָאֱלֹהִים אֲשֶׁר בִּירוּשָׁלִָם. מִן ״כֹּה אָמַר כּוֹרֶשׁ״ עַד כָּאן הַכְרָזַת הַכָּרוֹז וּשְׁלִיחוּת אִגֶּרֶת הַמִּכְתָּב:",3,0],[1,5,"לִיהוּדָה וּבִנְיָמִין. אוֹתָן רָאשֵׁי הָאָבוֹת אֲשֶׁר לַשְּׁבָטִים הַלָּלוּ שֶׁל יְהוּדָה וּבִנְיָמִין:",1,0],[1,5,"לְכָל הָעִיר. עִם כָּל אוֹתָם שֶׁהֵעִיר ה׳ רוּחוֹ לַעֲלוֹת וְלִבְנוֹת הַבַּיִת, עָלוּ לִירוּשָׁלַיִם לִבְנוֹת הַבַּיִת:",2,0],[1,6,"וְכָל סְבִיבוֹתֵיהֶם. וְכָל הָעַמִּים שֶׁהָיוּ שְׁכֵנֵיהֶם שֶׁל יִשְׂרָאֵל סִיְּעוּ וְהֶחֱזִיקוּ יְדֵי הַיְּהוּדִים בְּזָהָב וּבְכֶסֶף וּמַתָּנוֹת הַלָּלוּ לְמַעַן יוּכְלוּ לַעֲלוֹת לִירוּשָׁלַיִם:",1,0],[1,6,"לְבַד עַל כָּל הִתְנַדֵּב. כָּל זֹאת הָיוּ עוֹשִׂים שְׁכֵינֵי הַיְּהוּדִים לְבַד מַה שֶּׁהֵם מִתְנַדְּבִים בְּעַצְמָם לְבִנְיַן הַבַּיִת:",2,0],[1,7,"וַיִּתְּנֵם בְּבֵית אֱלֹהָיו. אֲשֶׁר נְתָנָם נְבוּכַדְנֶצַּר בְּבֵית עֲבוֹדַת כּוֹכָבִים שֶׁלּוֹ:",1,0],[1,8,"עַל יַד מִתְרְדָת הַגִּזְבָּר. כָּךְ שְׁמוֹ שֶׁל גִּזְבָּר אֲשֶׁר לְכוֹרֶשׁ, וְצִוָּהוּ כּוֹרֶשׁ לְהוֹצִיאָם:",1,0],[1,8,"וַיִּסְפְּרֵם. הַגִּזְבָּר הַזֶּה מָנָה אוֹתָם וּמְסָרָם לְשֵׁשְׁבַּצַּר לְמַעַן יִשָּׂאֵם וְיוֹלִיכֵם לִירוּשָׁלַיִם. וְאָמְרוּ רַבּוֹתֵינוּ: הוּא שֵׁשְׁבַּצַּר הוּא דָנִיֵּאל, וְלָמָּה נִקְרָא שְׁמוֹ שֵׁשְׁבַּצַּר? שֶׁעָמַד בְּשֵׁשׁ צָרוֹת:",2,0],[1,8,"הַנָּשִׂיא לִיהוּדָה. הוּא הַנָּשִׂיא אֲשֶׁר לְשֵׁבֶט יְהוּדָה:",3,0],[1,9,"מִסְפָּרָם שֶׁל כְּלֵי בֵּית ה׳:",1,0],[1,9,"אֲגַרְטְלֵי. מִינֵי כֵלִים הֵם:",2,0],[1,9,"מַחֲלָפִים. הֵם סַכִּינִים, וְהוּא לְשׁוֹן בֵּית הַחֲלָפוֹת, שֶׁעַל כֵּן שֶׁהָיוּ נוֹתְנִין בָּהּ הַסַּכִּינִין הָיְתָה נִקְרֵאת לִשְׁכַּת בֵּית הַחֲלָפוֹת:",3,0],[1,10,"כְּפוֹרֵי. מִזְרָקִים, וְנִקְרְאוּ כְּפוֹרֵי מִלְּשׁוֹן קִנּוּחַ כְּמוֹ דְּכָפַר יְדֵיהּ בִּגְלִימָא דְּחַבְרֵיהּ (בבא מציעא כד:), עַל שֵׁם שֶׁהַמְקַבֵּל דָּם בַּמִּזְרָק הָיָה מְקַנֵּחַ נִצּוֹצוֹת הַדָּם שֶׁנִּתְּזוּ עַל יָדוֹ בִּשְׂפַת הַמִּזְרָק:",1,0],[1,10,"מִשְׁנִים. שְׁנַיִם כֵּלִים אֲחֵרִים שֶׁל מִין אַחֵר:",2,0],[1,11,"כָּל כֵּלִים. עַתָּה כּוֹלֵל חֶשְׁבּוֹן הַמְּנוּיִין וְשֶׁאֵינָן מְנוּיִין כֻּלָּן בְּמִנְיָן אֶחָד, אֲבָל הַחֲשׁוּבִין הוּא מוֹנֶה:",1,0],[1,11,"הֵעָלוֹת. לְשׁוֹן (יִפָּעֵל):",2,0],[2,1,"וְאֵלֶּה בְּנֵי הַמְּדִינָה. אֵלֶּה בְּנֵי יִשְׂרָאֵל אֲשֶׁר מִמְּדִינַת אֶרֶץ יִשְׂרָאֵל הָעוֹלִים עַתָּה מִן הַשְּׁבִי אֲשֶׁר בַּגּוֹלָה לִירוּשָׁלַיִם:",1,0],[2,1,"וַיָּשׁוּבוּ. וְעַתָּה חָזְרוּ לִירוּשָׁלַיִם:",2,0],[2,1,"וִיהוּדָה. וּבְנֵי יְהוּדָה חָזְרוּ כָּל אֶחָד וְאֶחָד לְעִירוֹ:",3,0],[2,2,"אֲשֶׁר בָּאוּ. בְּנֵי הַמְּדִינָה הַלָּלוּ בַּתְּחִלָּה כַּאֲשֶׁר גָּלוּ מֵאֶרֶץ יִשְׂרָאֵל לְבָבֶל עִם זְרֻבָּבֶל וְגוֹ׳:",1,0],[2,2,"מִסְפָּר. הָרִאשׁוֹן פּ״א קְמוּצָה בְּגָדוֹל וְשֵׁם אָדָם הוּא, מִסְפַּר הַשֵּׁנִי פּ״א פְּתוּחָה וְדָבוּק הוּא:",2,0],[2,2,"אַנְשֵׁי עַם יִשְׂרָאֵל. הַלָּלוּ בְּנֵי אָדָם גְּדוֹלִים וַחֲשׁוּבִים הָיוּ, וְהָאֲחֵרִים הָיוּ מְשׁוּכִים אַחֲרֵיהֶם. וְעַל כֵּן מְנָאוּם אַחֲרֵיהֶם לְבַד:",3,0],[2,3,"בְּנֵי פַרְעוֹשׁ וְגוֹ׳. יֵשׁ בָּהֶם בַּפָּרָשָׁה שֶׁמַּזְכִּיר שֵׁם אֲבִיהֶם עַל שֵׁם בְּנֵי הַמִּשְׁפָּחָה, וְיֵשׁ מֵהֶם שֶׁמַּזְכִּירָם עַל שֵׁם מְקוֹמָם, לוֹמַר בְּנֵי מָקוֹם פְּלוֹנִי:",1,0],[2,36,"הַכֹּהֲנִים בְּנֵי יְדַעְיָה. עַד עַתָּה מָנָה בְּנֵי יְהוּדָה וּבִנְיָמִין, וּמֵעַכְשָׁיו הוּא מוֹנֶה וְהוֹלֵךְ הַכֹּהֲנִים וְהַלְוִיִּם, כְּמוֹ שֶׁנֶּאֱמַר לְמַעְלָה ״וַיָּקוּמוּ רָאשֵׁי הָאָבוֹת לִיהוּדָה וּבִנְיָמִין וְהַכֹּהֲנִים וְהַלְוִיִּם וְגוֹ׳״ (עזרא א:ה):",1,0],[2,41,"הַמְשׁוֹרְרִים. הַלְוִיִּם שֶׁהָיוּ מְשׁוֹרְרִים, וְכֵן הַשּׁוֹעֲרִים הֵם הַלְוִיִּם שֶׁהָיוּ שׁוֹעֲרִים מִשַּׁעֲרֵי בֵּית הַמִּקְדָּשׁ:",1,0],[2,43,"הַנְּתִינִים. עַכְשָׁיו הוּא מוֹנֶה אוֹתָם נְתִינִים שֶׁהָיוּ חוֹטְבֵי עֵצִים וְשׁוֹאֲבֵי מַיִם לָעֵדָה (יהושע ט:כז), וּמִשָּׁם הָיְתָה יוֹצֵאת פַּרְנָסָתָם:",1,0],[2,58,"וּבְנֵי עַבְדֵי שְׁלֹמֹה. עֲבָדִים הָיוּ לִשְׁלֹמֹה הַמֶּלֶךְ, וְהַלָּלוּ בָּנִים הָיוּ מִבְּנֵי בְנֵיהֶם:",1,0],[2,59,"וְאֵלֶּה הָעוֹלִים מִתֵּל מֶלַח וְגוֹ׳. וְאֵי זֶה מַעֲשֶׂה הִגִּיעַ לָהֶם וְלֹא יָכְלוּ לְהַגִּיד וְגוֹ׳:",1,0],[2,59,"וְזַרְעָם. שֶׁל אֲבוֹתָם לְפִי שֶׁאָבְדוּ יִחוּס שֶׁלָּהֶם וְלֹא יָדְעוּ אִם מִיִּשְׂרָאֵל הֵם:",2,0],[2,60,"בְּנֵי דְלָיָה וְגוֹ׳. גַּם הֵם בִּכְלַל אֵלֶּה הָעוֹלִים מִתֵּל מֶלַח (עזרא ב:נט):",1,0],[2,61,"אֲשֶׁר לָקַח. כָּל אֶחָד מִבְּנֵי בַרְזִלַּי הַגִּלְעָדִי לָקַח אִשָּׁה:",1,0],[2,61,"וַיִּקָּרֵא עַל שְׁמָם. וְהָיָה נִקְרָא שְׁמוֹ שֶׁל בַּרְזִלַּי עַל שְׁמָם, לְפִי שֶׁהֵם לָקְחוּ מִבְּנוֹתָיו:",2,0],[2,62,"אֵלֶּה. כֹּהֲנִים הַלָּלוּ הַמִּתְיַחֲסִים שֶׁהָיָה לָהֶם לְהִתְיַחֵס בְּאוֹתוֹ כְּתָב וְלֹא נִמְצָא כְּתַב יִחוּסָן:",1,0],[2,62,"וַיְגֹאֲלוּ. שֶׁהָיוּ מְגֹאָלִים וּמְגֹעָלִים שֶׁלֹּא יַעַבְדוּ עוֹד עִם שְׁאָר הַכֹּהֲנִים בַּעֲבוּר שֶׁלֹּא נִמְצָא כְתַב יִחוּסָן:",2,0],[2,63,"הַתִּרְשָׁתָא. הוּא נְחֶמְיָה בֶּן חֲכַלְיָה (נחמיה ח:ט), וְאָמְרוּ רַבּוֹתֵינוּ שֶׁנִּקְרָא שְׁמוֹ הַתִּרְשָׁתָא שֶׁהִתִּירוּ לוֹ חֲכָמִים לִשְׁתּוֹת יֵין נֶסֶךְ שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת עַל אֲשֶׁר הָיָה מַשְׁקֶה לַמֶּלֶךְ (ירושלמי קידושין ד,א):",1,0],[2,63,"מִקֹּדֶשׁ הַקֳּדָשִׁים. חַטָּאוֹת וַאֲשָׁמוֹת כִּשְׁאָר כֹּהֲנִים:",2,0],[2,63,"עַד עֲמֹד כֹּהֵן וְגוֹ׳. כְּאָדָם הָאוֹמֵר לַחֲבֵירוֹ עַד יְמוֹת הַמָּשִׁיחַ לֹא יַעֲלֶה דָּבָר זֶה, וְאֵינִי יָכוֹל לִפְתּוֹר עַד עֲמֹד כֹּהֵן לְאוּרִים וְתוּמִּים בְּבַיִת שֵׁנִי, לְפִי שֶׁמָּצִינוּ בְּפֶרֶק רִאשׁוֹן שֶׁל יוֹמָא (יומא כא:) שֶׁהָיָה בַּיִת שֵׁנִי חָסֵר מֵאוּרִים וְתוּמִּים:",3,0],[2,64,"כָּל הַקָּהָל כְּאֶחָד. כְּשֶׁהָיוּ כֻלָּם בְּיַחַד עִם הַכֹּהֲנִים וְהַלְוִיִּם וְהַנְּתִינִים הָיָה בָּהֶם חֶשְׁבּוֹן זֶה, וּבְנֵי יִשְׂרָאֵל הַמְּנוּיִים לְמַעְלָה הֵם שֶׁל שֵׁבֶט יְהוּדָה וּבִנְיָמִין, וְאוֹתָם אֲשֶׁר נֶחְסְרוּ מֵחֶשְׁבּוֹן זֶה שֶׁלֹּא תִמְצָאֵם לְמַעְלָה הֵם הָיוּ מִשְּׁאָר הַשְּׁבָטִים. וְכֵן מְפֹרָשׁ בְּסֵדֶר עוֹלָם (פרק כט): כָּל הַקָּהָל כְּאֶחָד אַרְבַּע רִבּוֹא וְגוֹ׳, וּבִפְרָטָן אֵינָן אֶלָּא שְׁלֹשִׁים אֶלֶף; שְׁלֹשָׁה עָשָׂר אֶלֶף הֵיכָן הֵם? אֶלָּא שֶׁעָלוּ מִשְּׁאָר הַשְּׁבָטִים:",1,0],[2,65,"מִלְּבַד עַבְדֵיהֶם וְאַמְהֹתֵיהֶם. שֶׁלֹּא הָיוּ בִּכְלַל הַקָּהָל:",1,0],[2,65,"וְלָהֶם מְשׁוֹרְרִים וּמְשׁוֹרְרוֹת מָאתָיִם. לְפִי שֶׁהָיוּ עוֹלִים בְּשִׂמְחָה מִבָּבֶל לְאֶרֶץ יִשְׂרָאֵל, הָיוּ צְרִיכִים לִמְשׁוֹרְרִים וּמְשׁוֹרְרוֹת כְּדֵי שֶׁיְּהוּ מְטַיְּלוֹת בָּהֶם בְּרֹב שִׂמְחָתָם:",2,0],[2,68,"הִתְנַדְּבוּ. הָיוּ מִתְנַדְּבִין לְבִנְיַן הַבַּיִת:",1,0],[2,69,"כְּכֹחָם. כְּפִי כֹּחָם וּמָמוֹנָם:",1,0],[2,69,"דַּרְכְּמוֹנִים. שֵׁם מַטְבֵּעַ שֶׁל זָהָב:",2,0],[2,69,"וְכָתְנוֹת כֹּהֲנִים. לְשָׁרֵת בָּהֶם:",3,0],[3,1,"וַיִּגַּע. כְּמוֹ וְהִגִּיעַ:",1,0],[3,1,"הַחֹדֶשׁ הַשְּׁבִיעִי. הוּא חֹדֶשׁ תִּשְׁרֵי וּבְנֵי יִשְׂרָאֵל אֲשֶׁר הָיוּ בֶּעָרִים מַה עָשׂוּ וַיֵּאָסְפוּ כֻלָּם כְּאֶחָד לִירוּשָׁלִָם:",2,0],[3,3,"וַיָּכִינוּ הַמִּזְבֵּחַ עַל מְכוֹנוֹתָיו. כְּדֵי לְהַקְרִיב עָלָיו קָרְבָּנוֹת, שֶׁהֲרֵי הָיוּ יְרֵאִים מֵעַמֵּי הָאֲרָצוֹת שֶׁלֹּא יְקַנְתְּרוּם וְשֶׁלֹּא יַלְשִׁינוּם לַמֶּלֶךְ. וּבָנוּ הַמִּזְבֵּחַ לַעֲלוֹת עָלָיו עוֹלוֹת לְמַעַן יִשְׁמְעוּ וְיָבִינוּ הָעַמִּים בַּדָּבָר אֲשֶׁר עָשָׂהוּ עַל פִּי הַמֶּלֶךְ וְעַל כֵּן יִמָּנְעוּ מִלְּקַנְתְּרָם לְבִנְיַן הַבַּיִת:",1,0],[3,3,"לַבֹּקֶר וְלָעָרֶב. תָּמִיד שֶׁל שַׁחַר וְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם (במדבר כח:ד):",2,0],[3,4,"וְעֹלַת יוֹם בְּיוֹם בְּמִסְפָּר. קָרְבְּנוֹת הֶחָג בְּמִסְפָּרָם כְּמִשְׁפָּטָם:",1,0],[3,5,"וְאַחֲרֵי כֵן. וּלְאַחַר הַסֻּכּוֹת הָיוּ מַקְרִיבִים קָרְבָּנוֹת בְּכָל יוֹם לַבֹּקֶר וְלָעֶרֶב:",1,0],[3,5,"וְלֶחֳדָשִׁים. וּלְרָאשֵׁי חֳדָשִׁים הָיוּ מַקְרִיבִים קָרְבָּנוֹת שֶׁל רָאשֵׁי חֳדָשִׁים:",2,0],[3,5,"וּלְכָל מוֹעֲדֵי ה׳. וְלִשְׁאָר מוֹעֲדוֹת קָרְבְּנֵיהֶם:",3,0],[3,5,"וּלְכָל מִתְנַדֵּב. וּלְכָל אוֹתָם הַמִּתְנַדְּבִים נִדְבוֹתֵיהֶם הָיוּ מְקַבְּלִים הַכֹּהֲנִים אוֹתָם לְהַקְרִיבָם, וּמִיּוֹם אֶחָד בְּתִשְׁרֵי הִתְחִילוּ לְהַקְרִיב קָרְבָּנוֹת וַעֲדַיִן לֹא נִבְנָה יְסוֹד הַבַּיִת:",4,0],[3,7,"לַצִּידוֹנִים וְלַצּוֹרִים. בְּנֵי צוֹר וְצִידוֹן שֶׁהָיוּ אוּמָּנִים לִבְנוֹת הַבַּיִת (מלכים א ה:טו-לב):",1,0],[3,7,"אֶל יָם יָפוֹא. דֶּרֶךְ הַיָּם הָיוּ מְבִיאִים אוֹתָם:",2,0],[3,7,"כְּרִשְׁיוֹן. כַּאֲשֶׁר הָיָה רְשׁוּת הַמֶּלֶךְ עֲלֵיהֶם לִבְנוֹת הַבַּיִת, כְּרִשְׁיוֹן לְשׁוֹן רְשׁוּת מִגִּזְרַת רָשָׁה שֶׁהֲרֵי מִן אָבָה יֹאמַר אֶבְיוֹן (דברים טו:ד) וּמִן צָבָה יֹאמַר צִבְיוֹן וּמִן חָזָה חִזָּיוֹן (ישעיהו כב:א) וּמִן רָעָה רַעְיוֹן (קהלת א:יז) מִן חָבָה חֶבְיוֹן (חבקוק ג:ד) וּמִן רָשָׁה יֹאמַר רְשׁוּת כְּמוֹ מִן עָנָה עֱנוּת (תהלים כב:כה) וּמִן שָׁבָה שְׁבוּת (יחזקאל כט:יד) וּמִן רָאָה רְאוּת (קהלת ה:י) וּמִן זָנָה זְנוּת (הושע ד:יא) נִמְצְאוּ רְשׁוּת וְרִשְׁיוֹן בָּאִין וְיוֹצְאִין מִגִּזְרָה אַחַת לְפִי שַׁעַר הַדִּקְדּוּק וְלָשׁוֹן אֶחָד הֵם, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן אֲרֶשֶׁת שְׂפָתֵינוּ (תהלים כא:ג) וְלֹא דִקְדֵּק בְּגִזְרָתוֹ וְאַף עַל פִּי כֵן שְׁנֵי פָנִים הַלָּלוּ קְרוֹבִים זֶה לָזֶה בְּמַשְׁמָעוּתָם:",3,0],[3,8,"בַּחֹדֶשׁ הַשֵּׁנִי. הוּא חֹדֶשׁ אִיָּר:",1,0],[3,8,"מֵהַשְּׁבִי. כָּל אוֹתָן שֶׁבָּאוּ מֵהַשִּׁבְיָה לִירוּשָׁלַיִם:",2,0],[3,8,"וַיַּעֲמִידוּ. הֶעֱמִידוּ הַלְוִיִּם הַמְשׁוֹרְרִים לְנַצֵּחַ וְלוֹמַר שִׁירָה לִפְנֵי הַבּוֹנִים בִּשְׁעַת בִּנְיַן יְסוֹד הַבַּיִת:",3,0],[3,8,"לְנַצֵּחַ. שְׁנֵי נִצּוּחוֹת הַלָּלוּ הֵם נִצּוּחֵי שִׁירָה, כְּמוֹ ״לַמְנַצֵּחַ (בִּנְגִינוֹת) מִזְמוֹר לְדָוִד״ (תהילים ד:א):",4,0],[3,9,"וַיַּעֲמֹד יֵשׁוּעַ. עָמְדוּ וְאָמְרוּ שִׁירָה בְּיַחַד סָבִיב עוֹשֵׂי מְלָאכַת יְסוֹד הַבַּיִת:",1,0],[3,10,"וְיִסְּדוּ. מִשְׁקָל חָזָק מִן יְסוֹד כְּמוֹ ״וְיִשְּׁבוּ טִירוֹתֵיהֶם״ (יחזקאל כה:ד), כֵּן וְיִשְּׁבוּ מִן יָשַׁב, וְיִסְּדוּ מִן יָסַד, וּמַשְׁמָעוּתָן וְיִסְּדוּ וַיִּשְׁבוּ, בְּמִשְׁקָל חָזָק בִּשְׁתֵּי יוֹדִי״ן אַחַת פְּעֻלָּה וְאַחַת שֶׁל יְסוֹד וּפִתְרוֹנָן הָיוּ מְיַסְּדִים מְיַשְּׁבִים:",1,0],[3,10,"וְיִסְּדוּ הַבּוֹנִים. וְהַבּוֹנִים מְיַסְּדִים אֶת יְסוֹד הֵיכַל ה׳, בְּשָׁעָה שֶׁהָיוּ מְנַצְּחִים בְּשִׁירָתָם וְהֶעֱמִידוּ הַכֹּהֲנִים מְלֻבָּשִׁים בִּגְדֵי כָבוֹד וַחֲצוֹצְרוֹת בִּידֵיהֶם לִתְקֹעַ בָּהֶם:",2,0],[3,10,"וְהַלְוִיִּם בְּנֵי אָסָף. הָיוּ מְשׁוֹרְרִים:",3,0],[3,10,"בַּמְצִלְתַּיִם. כְּמוֹ (תהלים קנ:ה) ״צִלְצְלֵי שָׁמַע״. כְּלֵי שִׁיר הֵם:",4,0],[3,10,"עַל יְדֵי דָוִד. שֶׁהָיוּ מְנַצְּחִים וּמְשׁוֹרְרִים שִׁירוֹת וְהוֹדָיוֹת שֶׁל דָּוִד מֶלֶךְ יִשְׂרָאֵל:",5,0],[3,11,"וַיַּעֲנוּ. לְשׁוֹן עֲנִיַּת זֶמֶר, כְּמוֹ ״וַתַּעַן לָהֶם מִרְיָם״ (שמות טו:כא):",1,0],[3,11,"וּבְהוֹדוֹת. וּבְהוֹדָיוֹת:",2,0],[3,11,"כִּי טוֹב. לְהוֹדוֹת לַה׳:",3,0],[3,11,"וְכָל הָעָם. שְׁאָר עַם יִשְׂרָאֵל:",4,0],[3,11,"עַל הוּסַד. כָּל הַשְּׂמָחוֹת הַלָּלוּ הָיוּ עוֹשִׂים עַל בִּנְיַן הַיְּסוֹד אֲשֶׁר הוּסַד בְּבֵית ה׳:",5,0],[3,12,"בְּיָסְדוֹ. בִּיסוֹד שֶׁלּוֹ מִן שֵׁם דָּבָר שֶׁל יוֹסַד, וּמִן יָסַד יֹאמַר בְּיָסְדוֹ, כְּמוֹ מִן חֹדֶשׁ ״בְּחָדְשׁוֹ״, מִן קֹדֶשׁ ״בְּקָדְשׁוֹ״:",1,0],[3,12,"זֶה הַבַּיִת. כְּשֶׁהָיוּ רוֹאִין בִּנְיַן בַּיִת זֶה הָיוּ בוֹכִין, מִתּוֹךְ שֶׁהָיוּ זוֹכְרִים אוֹתוֹ בִּנְיָן גָּדוֹל שֶׁל בַּיִת רִאשׁוֹן:",2,0],[3,12,"וְרַבִּים. אֲשֶׁר לֹא רָאוּ בִּנְיַן בַּיִת רִאשׁוֹן הָיוּ שְׂמֵחִין וּמְרִיעִין בְּשִׂמְחָה בְּקוֹל גָּדוֹל מֵרֹב שִׂמְחָתָן שֶׁיָּצְאוּ מִגָּלוּתָן:",3,0],[3,13,"וְאֵין הָעָם מַכִּירִים. אוֹתָן הַשּׁוֹמְעִים לֹא הָיוּ מַכִּירִים קוֹל תְּרוּעָה שֶׁל שִׂמְחָה מִפְּנֵי קוֹל בְּכִי הָעָם, שֶׁהֲרֵי הָעָם הַשְּׂמֵחִים הָיוּ מְרִיעִים תְּרוּעָה גְדוֹלָה, וְקוֹל הַבְּכִי נִשְׁמַע יוֹתֵר וְיוֹתֵר עַד לְמֵרָחוֹק:",1,0],[4,1,"צָרֵי יְהוּדָה וּבִנְיָמִין. הֵם הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר הוֹשִׁיב סַנְחֵרִיב בְּאֶרֶץ יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (מלכים ב יז:כד): ״וַיָּבֵא מֶלֶךְ אַשּׁוּר מִבָּבֶל וּמִכּוּתָה וּמֵעַוָּא וּמֵחֲמָת וּסְפַרְוָיִם, וַיּוֹשֶׁב אֹתָם בְּעָרֵי שֹׁמְרוֹן תַּחַת בְּנֵי יִשְׂרָאֵל״:",1,0],[4,2,"וַיֹּאמְרוּ לָהֶם נִבְנֶה עִמָּכֶם. הָיוּ אוֹמְרִים כָּךְ לְמַעַן תִּתְבַּטֵּל מְלֶאכֶת הַבַּיִת עַל יְדֵיהֶם שֶׁלֹּא לִבְנוֹת עוֹד:",1,0],[4,2,"מִימֵי אֵסַר חַדֹּן מֶלֶךְ אַשּׁוּר. בְּנוֹ שֶׁל סַנְחֵרִיב, שֶׁלְּאַחַר שֶׁסַּנְחֵרִיב הוֹשִׁיבָם שָׁם הֲרָגוּהוּ אַדְרַמֶּלֶךְ וְשַׂרְאֶצֶר בָּנָיו, וַיִּמְלֹךְ אֵסַר חַדֹּן בְּנוֹ תַּחְתָּיו. שֶׁנֶּאֱמַר (ישעיה לז:לח): ״וַיְהִי הוּא מִשְׁתַּחֲוֶה בֵּית נִסְרֹךְ אֱלֹהָיו וְאַדְרַמֶּלֶךְ וְשַׂרְאֶצֶר בָּנָיו הִכֻּהוּ בַחֶרֶב וְגוֹמֵר וַיִּמְלֹךְ אֵסַר חַדֹּן בְּנוֹ תַּחְתָּיו״:",2,0],[4,3,"כִּי אֲנַחְנוּ. אֶלָּא אֲנַחְנוּ לְבַדֵּנוּ נִבְנֶה כִּי זֶה מְשַׁמֵּשׁ בִּמְקוֹם אֶלָּא:",1,0],[4,4,"עַם הָאָרֶץ. הֵם צָרֵי יְהוּדָה וּבִנְיָמִין:",1,0],[4,4,"מְרַפִּים. לְבַטְּלָם מִמְּלַאכְתָּם:",2,0],[4,4,"לִבְנוֹת. כְּמוֹ מִלִּבְנוֹת, וְכֵן ״עַד כִּי חָדַל לִסְפֹּר״ (בראשית מא:מט):",3,0],[4,5,"וְסוֹכְרִים. כְּתִיב בְּסָמֶ״ךְ וּפִתְרוֹנוֹ כְּאִלּוּ כָּתוּב בְּשִׂי״ן שֶׁהָיוּ שׂוֹכְרִים יוֹעֲצִים כְּדֵי לְבַטֵּל הַמְּלָאכָה:",1,0],[4,5,"כָּל יְמֵי. מַלְכוּת כּוֹרֶשׁ וּמַלְכוּת אֲחַשְׁוֵרוֹשׁ אֲשֶׁר מָלַךְ אַחַר כּוֹרֶשׁ, עַד שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ שֶׁמָּלַךְ אַחַר אֲחַשְׁוֵרוֹשׁ, הָיְתָה הַמְּלָאכָה בְּטֵלָה:",2,0],[4,6,"וּבְמַלְכוּת אֲחַשְׁוֵרוֹשׁ. שֶׁמָּלַךְ אַחַר כּוֹרֶשׁ הוּא אֲחַשְׁוֵרוֹשׁ שֶׁלָּקַח אֶסְתֵּר (מגילה יא.):",1,0],[4,6,"כָּתְבוּ שִׂטְנָה. שֶׁלֹּא לִבְנוֹת בֵּית הַמִּקְדָּשׁ:",2,0],[4,6,"עַל יוֹשְׁבֵי יְהוּדָה וִירוּשָׁלִָם. לְהַלְשִׁינָם וּלְקַנְתְּרָם שֶׁלֹּא יִבְנוּ הַבַּיִת:",3,0],[4,7,"וּבִימֵי אַרְתַּחְשַׁשְׂתָּא. הוּא כּוֹרֶשׁ מֶלֶךְ פָּרַס. מִנְיַן אוֹתִיּוֹת שֶׁל כּוֹרֶשׁ עוֹלֶה לְמִנְיַן אוֹתִיּוֹת דָּרְיָוֶשׁ. וְכֵן שָׁנִינוּ בְּמַסֶּכֶת רֹאשׁ הַשָּׁנָה (ראש השנה ג:): הוּא כּוֹרֶשׁ, הוּא דָּרְיָוֶשׁ, הוּא אַרְתַּחְשַׁשְׂתָּא. כּוֹרֶשׁ עַל שֵׁם שֶׁמֶּלֶךְ כָּשֵׁר הָיָה, אַרְתַּחְשַׁשְׂתָּא עַל שֵׁם הַמַּלְכוּת. וּבְסֵדֶר עוֹלָם (סדר עולם רבה ל) מָצָאתִי: דָּרְיָוֶשׁ הוּא אַרְתַּחְשַׁשְׂתָּא, וְכָל הַמַּלְכוּת כֻּלָּהּ נִקְרֵאת אַרְתַּחְשַׁשְׂתָּא וְכוּ׳:",1,0],[4,7,"כָּתַב בִּשְׁלָם. כָּתַב מִכְתָּבוֹ בִּדְבָרִים שֶׁל שָׁלוֹם:",2,0],[4,7,"מִתְרְדָת טָבְאֵל. שֵׁם אָדָם הוּא, מִצָּרֵי יְהוּדָה וּבִנְיָמִין:",3,0],[4,7,"וּשְׁאָר כְּנָוֺתָו. חֲבֵרוֹתָיו וְסִיעוֹתָיו:",4,0],[4,7,"עַל אַרְתַּחְשַׁשְׂתָּא. אֶל אַרְתַּחְשַׁשְׂתָּא:",5,0],[4,7,"וּכְתָב הַנִּשְׁתְּוָן. וּכְתָב הָאִגֶּרֶת:",6,0],[4,7,"כָּתוּב אֲרָמִית. בְּאוֹתִיּוֹת אֲרָמִית:",7,0],[4,7,"וּמְתֻרְגָּם אֲרָמִית. הַמִּכְתָּב הָיָה מְפֹרָשׁ בְּלָשׁוֹן אֲרָמִית:",8,0],[4,8,"רְחוּם בַּעַל טְעֵם. רְחוּם הָיָה מַזְכִּיר וּבַעַל דְּבָרִים לְסַדֵּר הַמִּכְתָּב:",1,0],[4,8,"וְשִׁמְשַׁי סָפְרָא. וְשִׁמְשַׁי הָיָה סוֹפֵר, הוּא שִׁמְשַׁי בְּנוֹ שֶׁל הָמָן. וְכֵן דֶּרֶךְ הַמִּקְרָא לְהַזְכִּיר סוֹפֵר וּמַזְכִּיר שְׁנֵיהֶם בְּיַחַד, לְפִי שֶׁהֵם זְקוּקִים זֶה לָזֶה, הָאֶחָד מְסַדֵּר וּמַזְכִּירוֹ וְהַסּוֹפֵר כּוֹתֵב, שֶׁנֶּאֱמַר: ״אֱלִיחֹרֶף וַאֲחִיָּה בְּנֵי שִׁישָׁא סֹפְרִים יְהוֹשָׁפָט בֶּן אֲחִילוּד הַמַּזְכִּיר״ (מלכים א ד:ג). וּבְמָקוֹם אַחֵר נֶאֱמַר: ״וַיָּבֹא אֶלְיָקִים בֶּן חִלְקִיָּהוּ וְגוֹ׳״ (מלכים ב יח:יח) ״וְשֶׁבְנָא הַסֹּפֵר וְיוֹאָח בֶּן אָסָף הַמַּזְכִּיר״:",2,0],[4,8,"כְּתַבוּ אִגְּרָא. הַלָּלוּ שְׁנֵיהֶם רְחוּם וְשִׁמְשַׁי כָּתְבוּ הָאִגֶּרֶת כַּאֲשֶׁר צִוָּה אֲלֵיהֶם מִתְרְדָת וְטָבְאֵל, וְכֻלָּם הָיוּ מְיֻשָּׁבִים בְּעָרֵי שׁוֹמְרוֹן:",3,0],[4,8,"עַל יְרוּשְׁלֶם. עַל אוֹדוֹת בִּנְיַן בֵּית הַמִּקְדָּשׁ אֲשֶׁר בִּירוּשָׁלַיִם:",4,0],[4,8,"כְּנֵימָא. כַּאֲשֶׁר נֶאֱמַר, וְהוּא דֻּגְמַת לְשׁוֹן גְּמָרָא כִּדְבָּעִינַן לְמֵימַר קַמָּן:",5,0],[4,9,"אֱדַיִן. אָז:",1,0],[4,9,"רְחוּם. שֵׁם אָדָם:",2,0],[4,9,"בְּעֵל טְעֵם. מַזְכִּיר וּבַעַל דְּבָרִים:",3,0],[4,9,"וּשְׁאָר כְּנָוָתְהוֹן. וּשְׁאָר סִיעוֹתֵיהֶם:",4,0],[4,9,"דִּינָיֵא וַאֲפַרְסַתְכָיֵא וְגוֹ׳. הַלָּלוּ כֻּלָּם שֵׁמוֹת שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהוֹשִׁיב סַנְחֵרִיב בְּעָרֵי שׁוֹמְרוֹן:",5,0],[4,9,"אֲפָרְסָיֵא. הֵם פַּרְסִיִּים שֶׁהוֹשִׁיב סַנְחֵרִיב בְּעָרֵי שׁוֹמְרוֹן (מלכים ב יז:כד):",6,0],[4,9,"אַרְכְּוָי. הֵם בְּנֵי אֶרֶךְ, שֶׁנֶּאֱמַר: ״וְאֶרֶךְ וְאַכַּד וְכַלְנֵה״ (בראשית י:י):",7,0],[4,9,"בָּבְלָיֵא. הֵם בְּנֵי בָבֶל:",8,0],[4,9,"שׁוּשַׁנְכָיֵא. בְּנֵי שׁוּשַׁן הַבִּירָה:",9,0],[4,9,"עֵלְמָיֵא. בְּנֵי עֵילָם. מִכָּל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת הַלָּלוּ הוֹשִׁיב סַנְחֵרִיב בְּאֶרֶץ יִשְׂרָאֵל, וְכֻלָּן הָיוּ מְשִׁיבִין וּמַסְכִּימִים בִּשְׁלִיחוּת הַמִּכְתָּב זֶה:",10,0],[4,10,"וּשְׁאָר אוּמַּיָּא. וּשְׁאָר הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר הִגְלָה סַנְחֵרִיב, כֻּלָּם הִסְכִּימוּ:",1,0],[4,10,"אָסְנַפַּר. סַנְחֵרִיב (מלכים ב יח:יג)׃",2,0],[4,10,"רַבָּא וְיַקִּירָא. שֶׁהָיָה מֶלֶךְ גָּדוֹל וּמְכֻבָּד, שֶׁנֶּאֱמַר ״כֹּה אָמַר הַמֶּלֶךְ הַגָּדוֹל מֶלֶךְ אַשּׁוּר״ (ישעיה לו:ד):",3,0],[4,10,"וְהוֹתֵב הִמּוֹ. הוֹשִׁיב אוֹתָם:",4,0],[4,10,"בְּקִרְיָה דִּי שָׁמְרָיִן. בֶּעָרִים אֲשֶׁר סְבִיבוֹת שׁוֹמְרוֹן:",5,0],[4,10,"וּשְׁאָר עֲבַר נַהֲרָה. וּשְׁאָר הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר בְּעֵבֶר הַנָּהָר, לְפִי שֶׁהַנָּהָר נְהַר פְּרָת מַפְסִיק בֵּין אֶרֶץ יִשְׂרָאֵל לְבָבֶל, נִמְצְאוּ אוֹתָן עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁלְצַד אֶרֶץ יִשְׂרָאֵל הֵם בְּעֵבֶר הַנָּהָר לְאוֹתָן הָעוֹמְדִים בְּבָבֶל:",6,0],[4,10,"וּכְעֶנֶת. שֵׁם מָקוֹם וְאַנְשֵׁי כְעֶנֶת כֻּלָּם הָיוּ מַסְכִּימִים בִּשְׁלִיחוּת הַמִּכְתָּב הַזֶּה:",7,0],[4,11,"דְּנָה פַּרְשֶׁגֶן אִגַּרְתָּא. וְזֶהוּ פִּתְרוֹן הָאִגֶּרֶת:",1,0],[4,11,"פַּרְשֶׁגֶן. כְּמוֹ פַּתְשֶׁגֶן הַכְּתָב (אסתר ג:יד):",2,0],[4,11,"דִּי שְׁלַחוּ עֲלוֹהִי. אֲשֶׁר שָׁלְחוּ אֵלָיו:",3,0],[4,11,"עַל אַרְתַּחְשַׁשְׂתְּא. אֶל אַרְתַּחְשַׁשְׂתְּא:",4,0],[4,11,"עַבְדָךְ אֱנָשׁ עֲבַר נַהֲרָה וּכְעֶנֶת. עַבְדֶיךָ הֵם אַנְשֵׁי עֵבֶר הַנָּהָר וְאַנְשֵׁי כְעֶנֶת. כָּל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת הַמְּנוּיוֹת כָּאן נִכְלָלוֹת בִּכְלָל זֶה, שֶׁכֻּלָּן הָיוּ לְצַד אֶרֶץ יִשְׂרָאֵל שֶׁהוּא עֵבֶר הַנָּהָר לְאוֹתָם הַשּׁוֹכְנִים בְּבָבֶל. וְזֶהוּ תְּחִלַּת הַמִּכְתָּב: עַבְדָךְ אֱנָשׁ עֲבַר נַהֲרָה וְגוֹמֵר עַד לָא אִיתַי לָךְ:",5,0],[4,12,"יְדִיעַ לֶהֱוֵא לְמַלְכָּא. דָּבָר יָדוּעַ יִהְיֶה לַמֶּלֶךְ:",1,0],[4,12,"דִּי יְהוּדָיֵא. אֲשֶׁר הַיְּהוּדִים שֶׁעָלוּ מֵאִתְּךָ אֵלֵינוּ בָּאוּ לִירוּשָׁלַיִם:",2,0],[4,12,"קִרְיְתָא מָרָדְתָּא וּבִאישְׁתָּא בָּנַיִן. עִיר מוֹרֶדֶת וְחוֹטֵאת הֵם בּוֹנִים:",3,0],[4,12,"וְשׁוּרַיָּא שַׁכְלִילוּ. וְהַחוֹמוֹת יִסְּדוּ:",4,0],[4,12,"וְאֻשַּׁיָּא. הַכְּתָלִים:",5,0],[4,12,"יַחִיטוּ. לְשׁוֹן פְּתִיל, כְּמוֹ ״אִם מִחוּט״ (בראשית יד:כג), שֶׁהֵם חוֹפְרִים וּמְחַבְּרִים הַכְּתָלִים זֶה עִם זֶה:",6,0],[4,13,"כְּעַן יְדִיעַ. עַתָּה יָדוּעַ יִהְיֶה לַמֶּלֶךְ:",1,0],[4,13,"דִּי הֵן קִרְיְתָא דָךְ תִּתְבְּנֵא. אֲשֶׁר אִם הָעִיר הַזֹּאת תִּבָּנֶה:",2,0],[4,13,"דָךְ. זֹאת:",3,0],[4,13,"וְשׁוּרַיָּא יִשְׁתַּכְלְלוּן. וְהַחוֹמוֹת יִהְיוּ מְיֻסָּדוֹת׃",4,0],[4,13,"מִנְדָּה בְלוֹ וַהֲלָךְ. מִינֵי מִסִּים הֵם וְכֶסֶף גֻּלְגֹּלֶת:",5,0],[4,13,"לֹא יִנְתְּנוּן. לֹא יִתְּנוּ עוֹד מַס:",6,0],[4,13,"וְאַפְתֹּם מְלָכִים תְּהַנְזִיק. וּמַס הַמְּלָכִים תֻּזַּק שֶׁלֹּא יִתְּנוּ עוֹד מַס לַמְּלָכִים:",7,0],[4,14,"כְּעַן כָּל קֳבֵל דִּי מְלַח הֵיכְלָא מְלַחְנָא. עַתָּה כָּל כְּנֶגֶד דָּבָר זֶה אֲשֶׁר חֻרְבַּן הַהֵיכָל אָנוּ רוֹצִים לְהַחֲרִיב, דִּי מְלַח לְשׁוֹן חוּרְבָּן וְשִׁמָּמוֹן כְּמוֹ ״אֶרֶץ מְלֵחָה וְלֹא תֵשֵׁב״ (ירמיה יז:ו):",1,0],[4,14,"מְלַחְנָא. אָנוּ רוֹצִים לִסְתּוֹר וּלְהַחֲרִיב:",2,0],[4,14,"וְעַרְוַת מַלְכָּא. וּבִזְיוֹן הַמֶּלֶךְ:",3,0],[4,14,"לָא אֲרִיךְ. אֵינוֹ הָגוּן לָנוּ לִרְאוֹת, אֲרִיךְ הָגוּן כְּמוֹ ״אֲרִיךְ אוֹ לָא אֲרִיךְ״ בְּמַסֶּכֶת סֻכָּה:",4,0],[4,14,"עַל דְּנָה. עַל זֹאת שָׁלַחְנוּ וְהוֹדַעְנוּ לַמֶּלֶךְ׃",5,0],[4,15,"דִּי יְבַקַּר. אֲשֶׁר יְבַקֵּר וְיִדְרֹשׁ הַדּוֹרֵשׁ בְּסֵפֶר הַזִּכְרוֹנוֹת שֶׁל אֲבוֹתֶיךָ הַמְּלָכִים הָרִאשׁוֹנִים:",1,0],[4,15,"וּתְהַשְׁכַּח. וְתִמְצָא בְּסֵפֶר הַזִּכְרוֹנוֹת וְתֵדַע כִּי הָעִיר הַזֹּאת עִיר מוֹרֶדֶת וּמַזֶּקֶת הַמְּלָכִים וְהַמְּדִינוֹת׃",2,0],[4,15,"וְאֶשְׁתַּדּוּר עָבְדִין בְּגַוַּהּ. וּמֶרֶד הָיוּ עוֹשִׂים יוֹשְׁבֶיהָ בְּתוֹכָהּ, שֶׁהָיוּ יִשְׂרָאֵל מוֹרְדִין בְּמַלְכֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",3,0],[4,15,"מִן יוֹמָת עָלְמָא. מִימוֹת הָעוֹלָם, מִיָּמִים קַדְמוֹנִים, כָּךְ הָיָה מִנְהָגָם לִמְרוֹד בְּמַלְכֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",4,0],[4,15,"עַל דְּנָה. עַל כָּךְ הָיְתָה הָעִיר הַזֹּאת חֲרֵבָה:",5,0],[4,16,"מְהוֹדְעִין אֲנַחְנָה לְמַלְכָּא. מוֹדִיעִין אֲנַחְנָא לַמֶּלֶךְ:",1,0],[4,16,"דִּי הֵן קִרְיְתָא דָךְ. אֲשֶׁר אִם הָעִיר הַזֹּאת תִּבָּנֶה וְחוֹמוֹתֶיהָ מְיֻסָּדִין:",2,0],[4,16,"לָקֳבֵל דְּנָה. כְּנֶגֶד כֵּן וּבִשְׁבִיל כָּךְ אֵין לְךָ חֵלֶק בְּכָל עֲבַר נַהֲרָא, לְפִי שֶׁיִּשְׂרָאֵל יִהְיוּ מוֹרְדִין בְּךָ וְיִקְחוּ הַכֹּל מִיָּדֶךָ:",3,0],[4,16,"בַּעֲבַר נַהֲרָא. הִיא כָּל הָאָרֶץ שֶׁל צַד אֶרֶץ יִשְׂרָאֵל שֶׁהוּא עֵבֶר הַנָּהָר לְאוֹתָן שֶׁבְּבָבֶל:",4,0],[4,17,"פִּתְגָמָא שְׁלַח מַלְכָּא. דָּבָר שָׁלַח הַמֶּלֶךְ׃",1,0],[4,17,"עַל רְחוּם בְּעֵל טְעֵם. אֶל רְחוּם הַמַּזְכִּיר וְשִׁמְשַׁי הַסּוֹפֵר וּלְשָׁאר סִיעוֹתֵיהֶם הַיּוֹשְׁבִים בְּעָרֵי שׁוֹמְרוֹן, וּלְשָׁאר הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר בְּעֵבֶר הַנָּהָר לְצַד אֶרֶץ יִשְׂרָאֵל:",2,0],[4,17,"שְׁלָם וּכְעֶת. מְקוֹמוֹת הֵם, וּכְעֶת כְּמוֹ ״וּכְעֶנֶת״ (עזרא ד:יא), פְּעָמִים קוֹרְהוּ כָּךְ וּפְעָמִים כָּךְ:",3,0],[4,18,"נִשְׁתְּוָנָא. כְּתָב הַנִּשְׁתְּוָן אֲשֶׁר שְׁלַחְתֶּם אֵלֵינוּ הָיָה מְפֹרָשׁ וְקָרוּי לְפָנַי׃",1,0],[4,19,"שִׂים טְעֵם. וּמֵאִתִּי הָיְתָה שִׂימַת דְּבַר צִוּוּי אֲשֶׁר צִוִּיתִי:",1,0],[4,19,"וּבַקַּרוּ וְהַשְׁכַּחוּ. וּבָדְקוּ בְּסֵפֶר הַזִּכְרוֹנוֹת הַמְּלָכִים וּמָצְאוּ כָתוּב אֲשֶׁר הָעִיר הַזֹּאת מִימוֹת הָעוֹלָם הָיְתָה מִתְנַשֵּׂאת וּמִתְרוֹמֶמֶת עַל כָּל מַלְכֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",2,0],[4,19,"וּמְרַד. וְסַרְבָנוּת הָיוּ עוֹשִׂים בָּהּ לִמְרוֹד בְּמַלְכֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",3,0],[4,20,"וּמַלְכִין תַּקִּיפִין. וּמְלָכִים חֲזָקִים הָיוּ בִּירוּשָׁלַיִם שֶׁהָיוּ מוֹשְׁלִים וְשַׁלִּיטִים בְּכָל עֵבֶר הַנָּהָר שֶׁל צַד אֶרֶץ יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר בִּשְׁלֹמֹה ״כִּי הוּא רֹדֶה בְּכָל עֵבֶר הַנָּהָר וְגוֹ׳״ (מלכים א ד:ה). וּמִסִּים וְכֶסֶף גֻּלְגֹּלֶת הָיָה נָתוּן לָהֶם, שֶׁהָיוּ הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מַעֲלִין לָהֶם מַס:",1,0],[4,21,"כְּעַן שִׂימוּ טְעֵם. עַתָּה שִׂימוּ דָבָר לְהַכְרִיז בָּאָרֶץ לְבַטֵּל אֲנָשִׁים הַלָּלוּ בְּנֵי יִשְׂרָאֵל מִן הַבִּנְיָן, וְהָעִיר הַזֹּאת יְרוּשָׁלַיִם לֹא תִבָּנֶה עַד אֲשֶׁר מִמֶּנִּי יוּשַׂם הַדָּבָר לִבְנוֹת הָעִיר עַל דַּעְתִּי וּרְשׁוּתִי:",1,0],[4,22,"וּזְהִירִין הֱווֹ שָׁלוּ. וּזְהִירִין תִּהְיוּ לַעֲשׂוֹת דִּחוּי וּשְׁגָגָה, שָׁלוּ דשטורביר בְּלַעַ״ז:",1,0],[4,22,"לְמֶעְבַּד עַל דְּנָה. לַעֲשׂוֹת עַל כָּךְ:",2,0],[4,22,"לָמָּה יִשְׂגֵּא. מַדּוּעַ יִגְדַּל מַעֲשֵׂה הַשְׁחָתָה בָּעִיר הַזֹּאת לְהַזִּיק הַמְּלָכִים. עַד כָּאן תְּשׁוּבַת כּוֹרֶשׁ אֲשֶׁר הֵשִׁיב:",3,0],[4,23,"אֱדַיִן. אָז:",1,0],[4,23,"דִּי פַרְשֶׁגֶן. מִן פִּתְרוֹן כְּתַב הַנִּשְׁתְּוָן שֶׁל אַרְתַּחְשַׁשְׂתְּא הַמֶּלֶךְ הוּא כּוֹרֶשׁ הָיָה הַמַּעֲשֶׂה הַזֶּה:",2,0],[4,23,"קֱרִי קֳדָם. שֶׁהָיָה כְּתָב הַנִּשְׁתְּוָן קָרוּי לִפְנֵי רְחוּם וְשִׁמְשַׁי וְסִיעָתֵיהֶם, וְהָלְכוּ בִּמְרוּצָה וּבְבֶהָלָה לִירוּשָׁלַיִם אֶל הַיְּהוּדִים, וּבִטְּלוּ אוֹתָם בִּזְרוֹעַ וְכֹחַ שֶׁלֹּא לִבְנוֹת עוֹד הַבִּנְיָן:",3,0],[4,23,"עַל יְהוּדָיֵא. אֶל הַיְּהוּדִים:",4,0],[4,23,"הֵמּוֹ. הֵם:",5,0],[4,24,"בֵּאדַיִן. אָז הָיְתָה בְּטֵלָה מְלֶאכֶת בִּנְיַן בֵּית אֱלֹהִים אֲשֶׁר בִּירוּשָׁלַיִם עַד שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ מֶלֶךְ פָּרָס. שֶׁאַחַר כּוֹרֶשׁ מָלַךְ אֲחַשְׁוֵרוֹשׁ שֶׁלָּקַח אֶסְתֵּר, וְאַחַר אֲחַשְׁוֵרוֹשׁ מָלַךְ דָּרְיָוֶשׁ בְּנוֹ שֶׁל אֲחַשְׁוֵרוֹשׁ שֶׁהוּא בֶּן אֶסְתֵּר. וּמִשְּׁנַת אַחַת לְכוֹרֶשׁ מֶלֶךְ פָּרַס עַד שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ שְׁמֹנֶה עֶשְׂרֵה שָׁנָה, שֶׁהִשְׁלִימוּ שִׁבְעִים שָׁנָה לְחָרְבוֹת יְרוּשָׁלַיִם. שֶׁהֲרֵי מֵחֻרְבַּן הַבַּיִת שֶׁגָּלָה צִדְקִיָּהוּ עַד שְׁנַת אַחַת לְכוֹרֶשׁ חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה, כַּמְפֹרָשׁ בְּסֵדֶר עוֹלָם (פרק כט). וּשְׁמֹנֶה עֶשְׂרֵה שָׁנָה מִשְּׁנַת א׳ לְכוֹרֶשׁ עַד שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ, נִמְצְאוּ שִׁבְעִים שָׁנָה שְׁלֵמִים. וּבִשְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ הִתְחִילוּ לִבְנוֹת הַבִּנְיָן עַד שֶׁגְּמָרוּהוּ:",1,0],[5,1,"וְהִתְנַבִּי חַגַּי נְבִיאָה. וְעַתָּה בִּשְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ נִתְנַבְּאוּ חַגַּי וּזְכַרְיָה הַנְּבִיאִים אֶל הַיְּהוּדִים אֲשֶׁר בְּאֶרֶץ יְהוּדָה וּבִירוּשָׁלַיִם בְּשֵׁם אֱלֹהֵי יִשְׂרָאֵל אֲלֵיהֶם לִבְנוֹת בִּנְיַן הַבַּיִת בְּלֹא רְשׁוּת הַמֶּלֶךְ דָּרְיָוֶשׁ:",1,0],[5,1,"עַל יְהוּדָיֵא. אֶל הַיְּהוּדִים:",2,0],[5,1,"עֲלֵיהוֹן. אֲלֵיהֶם:",3,0],[5,2,"בֵּאדַיִן. אָז:",1,0],[5,2,"וְשָׁרִיו. הִתְחִילוּ לִבְנוֹת בֵּיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר בִּירוּשָׁלַיִם, וְעִמָּהֶם הַנְּבִיאִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹזְרִין וּמְסַיְּעִין לָהֶם:",2,0],[5,3,"בֵּהּ זִמְנָא אֲתָה עֲלֵיהוֹן. בְּאוֹתוֹ הַזְּמַן בָּאוּ עֲלֵיהֶם הַלָּלוּ צָרֵי יְהוּדָה וּבִנְיָמִין לְקַנְתֵּר וּלְהַלְשִׁין עֲלֵיהֶם עַל עֵסֶק הַבִּנְיָן:",1,0],[5,3,"פַּחַת עֲבַר נַהֲרָה. שִׁלְטוֹן שֶׁל עֵבֶר הַנָּהָר:",2,0],[5,3,"וּכְנָוָתְהוֹן. וְסִיעָתְהוֹן:",3,0],[5,3,"וְכֵן אָמְרִין לְהוֹם. וְכֵן הָיוּ אוֹמְרִים לָהֶם:",4,0],[5,3,"מַן שָׂם. מִי צִוָּה לָכֶם דְּבַר הַבַּיִת לִבְנוֹת?",5,0],[5,3,"וְאֻשַּׁרְנָא דְנָה לְשַׁכְלָלָה. הַכְּתָלִים הָאֵלֶּה לְיַסֵּד, כְּמוֹ ״וְאֻשַּׁיָּא יְחִיטוּ״ (עזרא ד:יב), וּבִנְיַן חוֹמוֹת לְבֵנִים. כָּךְ חִבְּרוֹ מְנַחֵם:",6,0],[5,4,"אֱדַיִן. אָז:",1,0],[5,4,"כְּנֵמָא. כַּאֲשֶׁר נֶאֱמַר:",2,0],[5,4,"אֲמַרְנָא לְהוֹם. אָמְרוּ לָהֶם לְיִשְׂרָאֵל אוֹתָן צָרֵי יְהוּדָה וּבִנְיָמִין:",3,0],[5,4,"מַן אִינּוּן. מִי הֵם שְׁמוֹת הָאֲנָשִׁים?",4,0],[5,4,"דִּי דְנָה. אֲשֶׁר זֶה הַבִּנְיָן הֵם בּוֹנִים:",5,0],[5,5,"וְעֵין אֱלָהֲהוֹם. וְעֵינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אֱלֹהֵיהֶם הָיְתָה עַל זִקְנֵי הַיְּהוּדִים לְהַעֲלוֹתָם בִּמְלֶאכֶת הַבִּנְיָן:",1,0],[5,5,"וְלָא בַטִּלוּ הִמּוֹ. וְלֹא בִּטְּלוּ הֵם אֶת הַבּוֹנִים:",2,0],[5,5,"עַד טַעְמָא לְדָרְיָוֶשׁ יְהָךְ. וְהֵשִׁיבוּ זִקְנֵי הַיְּהוּדִים דָּבָר לְאוֹתָן הַצָּרִים שֶׁלֹּא יְבַטְּלוּ אֶת הַבִּנְיָן עַד אֲשֶׁר יֵלֵךְ הַדָּבָר לְדָרְיָוֶשׁ הַמֶּלֶךְ:",3,0],[5,5,"וֶאֱדַיִן יְתִיבוּן. וְאָז יָשִׁיבוּ הַיְּהוּדִים כְּתַב הַנִּשְׁתְּוָן עַל כָּךְ, עַל תְּשׁוּבָתוֹ שֶׁל דָּרְיָוֶשׁ:",4,0],[5,6,"פַּרְשֶׁגֶן. פִּתְרוֹן פַּתְשֶׁגֶן הָאִגֶּרֶת:",1,0],[5,6,"וּכְנָוָתֵהּ. וְסִיעוֹתָיו:",2,0],[5,6,"אֲפַרְסְכָיֵא. אֻמָּה אַחַת הֵן שֶׁהָיוּ בְּסִיעוֹתֵיהֶם:",3,0],[5,6,"עַל דָּרְיָוֶשׁ מַלְכָּא. אֶל דָּרְיָוֶשׁ הַמֶּלֶךְ:",4,0],[5,7,"עֲלוֹהִי. אֵלָיו:",1,0],[5,7,"וְכִדְנָה כְּתִיב בְּגַוֵּהּ. וְכָךְ הָיָה כָתוּב בְּתוֹכָהּ שֶׁל אִגֶּרֶת:",2,0],[5,7,"שְׁלָמָא כֹּלָּא. כָּל הַשָּׁלוֹם יִהְיֶה לוֹ:",3,0],[5,8,"יְדִיעַ לֶהֱוֵא לְמַלְכָּא. דָּבָר יָדוּעַ יִהְיֶה לַמֶּלֶךְ:",1,0],[5,8,"דִּי אֲזַלְנָא. אֲשֶׁר הָלַכְנוּ אֶל אֶרֶץ יְהוּדָה הַמְּדִינָה לְבֵית אֱלוֹהַּ הַגָּדוֹל:",2,0],[5,8,"וְהוּא מִתְבְּנֵא. וְהוּא הַבַּיִת בָּנוּי:",3,0],[5,8,"גְּלָל. מַרְמְרָ״א בְּלַעַ״ז:",4,0],[5,8,"וְאָע מִתְּשָׂם בְּכֻתְלַיָּא. וְעֵצִים נְתוּנִים וּמְשׂוּמִים בַּכְּתָלִים כְּדֵי לְהַחֲזִיק הַבִּנְיָן לְמַעַן יַעֲמֹד יָמִים רַבִּים:",5,0],[5,8,"וַעֲבִידְתָא דָךְ. וּמְלָאכָה זֹאת:",6,0],[5,8,"אָסְפַּרְנָא מִתְעַבְדָא. מְהֵרָה הָיְתָה נַעֲשֵׂית:",7,0],[5,8,"אָסְפַּרְנָא. אֶפַנְטוֹמִינְשׁ בְּלַעַ״ז:",8,0],[5,8,"וּמַצְלַח בְּיֶדְהֹם. וְהֻצְלַח מַעֲשֶׂה זֶה בִּידֵיהֶם:",9,0],[5,9,"אֱדַיִן. אָז כְּשֶׁרָאִינוּ הַבִּנְיָן שָׁאַלְנוּ לַזְּקֵנִים הָאֵלֶּה:",1,0],[5,9,"כְּנֵמָא אֲמַרְנָא לְהוֹם. כַּאֲשֶׁר נֶאֱמַר בְּסָמוּךְ אָמַרְנוּ אֲלֵיהֶם:",2,0],[5,9,"מַן שָׂם לְכֹם. מִי שָׂם לָכֶם דְּבַר הַבַּיִת הַזֶּה לִבְנוֹתוֹ, וּכְתָלִים הַלָּלוּ לִיסֹד?",3,0],[5,9,"וְאֻשַּׁרְנָא. בִּנְיַן חוֹמַת לְבֵנִים:",4,0],[5,10,"וְאַף שְׁמָהָתְהֹם. וְאַף שְׁמוֹתָם שֶׁל בּוֹנִים רָאשֵׁי הַבִּנְיָן שָׁאַלְנוּ לָהֶם כְּדֵי לְהוֹדִיעֲךָ:",1,0],[5,10,"דִּי נִכְתֻּב. אֲשֶׁר נִכְתּוֹב שְׁמוֹת הָאֲנָשִׁים אֵלֶיךָ:",2,0],[5,10,"דִּי בְרָאשֵׁיהֹם. אֲשֶׁר בְּעַצְמָם וּבִרְשׁוּתָם קָמוּ לִבְנוֹת הַבַּיִת:",3,0],[5,11,"וּכְנֵמָא פִתְגָמָא. כְּמוֹ שֶׁנֶּאֱמַר הַדָּבָר:",1,0],[5,11,"הֲתִיבוּנָא. הָשִׁיבוּ לָנוּ דָּבָר:",2,0],[5,11,"אֲנַחְנָא הִמּוֹ. אֲנַחְנוּ הֵם עַבְדָיו שֶׁל אֱלֹהֵי הַשָּׁמַיִם וְהָאָרֶץ:",3,0],[5,11,"וּבִנְיַן בַּיְתָא. וַאֲנַחְנוּ בּוֹנִין הַבַּיִת אֲשֶׁר הָיָה בָּנוּי קוֹדֶם לָכֵן שָׁנִים רַבּוֹת:",4,0],[5,11,"וּמֶלֶךְ לְיִשְׂרָאֵל רַב. וּמֶלֶךְ גָּדוֹל שֶׁהָיָה לְיִשְׂרָאֵל הוּא שְׁלֹמֹה הַמֶּלֶךְ בָּנָה אוֹתוֹ וְיִסַּד אוֹתוֹ:",5,0],[5,12,"לָהֵן. וְעַכְשָׁיו מִפְּנֵי אֲשֶׁר הִכְעִיסוּ אֲבוֹתֵינוּ לֵאלֹהֵי הַשָּׁמַיִם מָסַר אוֹתָם בְּיַד מֶלֶךְ בָּבֶל הַכַּשְׂדִּי וְהַבַּיִת הַזֶּה הֶחֱרִיב וְאֶת הָעָם הִגְלָה לְבָבֶל:",1,0],[5,13,"בְּרַם. אַךְ בְּשָׁנָה אַחַת לְכוֹרֶשׁ מֶלֶךְ בָּבֶל צִוָּה כוֹרֶשׁ בַּדָּבָר הַזֶּה לִבְנוֹת הַבַּיִת:",1,0],[5,14,"וְאַף מָאנַיָּא. כְּלֵי הַקֹּדֶשׁ שֶׁל כֶּסֶף וְזָהָב אֲשֶׁר הוֹצִיא נְבוּכַדְנֶצַּר מִן הַהֵיכָל שֶׁבִּירוּשָׁלַיִם וְהוֹלִיכָם לְהֵיכָלוֹ שֶׁבְּבָבֶל, הוֹצִיא אוֹתָם כּוֹרֶשׁ מֵהֵיכַל מֶלֶךְ בָּבֶל וּמְסָרָם לְיַד שֵׁשְׁבַּצַּר דָּנִיֵּאל שֶׁשְּׁמוֹ כָּךְ:",1,0],[5,14,"וְהֵיבִיל הִמּוֹ. וְהוֹלִיךְ אוֹתָם:",2,0],[5,14,"הַנְפֵּק הִמּוֹ. הוֹצִיא אוֹתָם:",3,0],[5,14,"דִּי פֶחָה שְׁמֵהּ. שֶׁהוּא הָיָה נָשִׂיא וּפַחַת, וְנִקְרָא שְׁמוֹ פֶחָה:",4,0],[5,15,"וַאֲמַר לֵהּ. וְכָךְ אָמַר לוֹ כּוֹרֶשׁ לְשֵׁשְׁבַּצַּר: אֵלֶּה הַכֵּלִים קַח וְלֵךְ וְהוֹרֵד אוֹתָם בַּהֵיכָל אֲשֶׁר בִּירוּשָׁלַיִם וּבֵיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יְהֵא בָּנוּי עַל מְקוֹמוֹ:",1,0],[5,16,"אֱדַיִן. אָז:",1,0],[5,16,"שֵׁשְׁבַּצַּר דֵּךְ. זֶה בָּא וְנָתַן כָּתְלֵי בֵּיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר בִּירוּשָׁלַיִם, וּמֵאָז וְעַד עַתָּה הָיָה הַבַּיִת בָּנוּי וְלֹא נִגְמַר הַבִּנְיָן:",2,0],[5,17,"וּכְעַן. וְעַתָּה אִם עַל הַמֶּלֶךְ טוֹב יִהְיֶה הַדָּבָר יָדוּעַ וּמְבֻקָּר בְּבֵית גְּנָזָיו שֶׁל מֶלֶךְ אֲשֶׁר שָׁם בְּבָבֶל:",1,0],[5,17,"הֵן אִיתַי. אִם יֵשׁ הַמַּעֲשֶׂה הַזֶּה אֲשֶׁר מִפִּי כּוֹרֶשׁ יָצָא דָּבָר לִבְנוֹת בַּיִת זֶה אֲשֶׁר בִּירוּשָׁלַיִם:",2,0],[5,17,"וּרְעוּת מַלְכָּא. רְצוֹן הַמֶּלֶךְ עַל כֵּן יִשְׁלַח אֵלֵינוּ:",3,0],[5,17,"עֲלֶינָא. אֵלֵינוּ. עַד כָּאן מִכְתַּב הָאִגֶּרֶת אֲשֶׁר שָׁלְחוּ תַּתְּנַי וּשְׁתַר בּוֹזְנַי:",4,0],[6,1,"בֵּאדַיִן. אָז כַּאֲשֶׁר הִגִּיעַ הַמִּכְתָּב לְיַד דָּרְיָוֶשׁ:",1,0],[6,1,"שָׂם טְעֵם. צִוָּה הַמֶּלֶךְ הַדָּבָר:",2,0],[6,1,"וּבַקַּרוּ. וּבָדְקוּ בְּבֵית הַסְּפָרִים שֶׁהָאוֹצָרוֹת מוּנָּחִים שָׁם בְּבָבֶל:",3,0],[6,2,"וְהִשְׁתְּכַח בְּאַחְמְתָא. וְנִמְצָא מִכְתָּב שֶׁל מְגִלָּה אַחַת שָׁם בְּאַחְמְתָא, כֵּן פָּתְרוּ אַנְשֵׁי הַפִּתְרוֹן שֶׁהוּא כְּלִי הֶעָשׂוּי לְאִגְּרוֹת וּלְגִלְיוֹנִים וְלִסְפָרִים, וְהֶעֱמִידוּהוּ מִגִּזְרַת ״חֵמֶת מַיִם״ (בראשית כא:יד), וְהָאָלֶ״ף אֲשֶׁר בַּתֵּיבָה אֵינָהּ עִקָּר כְּיֶתֶר הַמִּלִּין אֲשֶׁר בִּשְׁאָר לְשׁוֹן אֲרָמִית:",1,0],[6,2,"בְּבִירְתָא. בְּאוֹתָהּ בִּירָה אֲשֶׁר בְּמָדַי הַמְּדִינָה:",2,0],[6,2,"וְכֵן כְּתִיב. וְכֵן הָיָה כָּתוּב בְּתוֹכָהּ זִכָּרוֹן שֶׁלָּהּ:",3,0],[6,3,"בֵּית אֱלָהָא בִירוּשְׁלֶם. בְּבֵית אֱלֹהִים בִּירוּשָׁלַיִם מָה יְהֵא עָלָיו? הַבַּיִת יִבָּנֶה:",1,0],[6,3,"אֲתַר דִּי דָבְחִין. שֶׁהוּא מָקוֹם שֶׁזּוֹבְחִים שָׁם זֶבַח:",2,0],[6,3,"וְאֻשּׁוֹהִי מְסוֹבְלִין. וְכוֹתְלָיו יִהְיוּ מְיֻסָּדִין, כְּמוֹ ״וְאֻשַּׁיָּא יַחִיטוּ״ (עזרא ד:יב):",3,0],[6,3,"רוּמֵיהּ אַמִּין שִׁתִּין. רוּם הַבַּיִת שִׁשִּׁים אַמָּה וְשִׁשִּׁים אַמָּה רָחְבּוֹ:",4,0],[6,4,"נִדְבָּכִין. לְשׁוֹן כְּתָלִים וְקִירוֹת הַכְּתָלִים הָיוּ שֶׁל אֶבֶן גָּלָל, גָּלָל מרמר״א בְּלַעַ״ז:",1,0],[6,4,"וְנִדְבָּךְ. וְכוֹתֶל שֶׁל עֵץ חָדָשׁ מִבִּפְנִים כְּעִנְיַן בִּנְיַן הַבַּיִת אֲשֶׁר בָּנָה שְׁלֹמֹה (מלכים א ו:טו-יח):",2,0],[6,4,"וְנִפְקְתָא. וְהוֹצָאָה לְצֹרֶךְ הַבַּיִת וּלְשָׁאָר דְּבָרִים אֲשֶׁר לַבַּיִת תִּנָּתֵן לָהֶם מִבֵּית הַמֶּלֶךְ:",3,0],[6,5,"וְאַף מָאנֵי. וְאַף כְּלֵי הַקֹּדֶשׁ שֶׁל בֵּית הָאֱלֹהִים שֶׁל זָהָב וְכֶסֶף אֲשֶׁר נְבוּכַדְנֶצַּר הוֹצִיאָם מִן הֵיכָל שֶׁבִּירוּשָׁלַיִם וְהוֹלִיכָם לְבָבֶל:",1,0],[6,5,"וְהֵיבִל. אֲשֶׁר הוֹלִיךְ:",2,0],[6,5,"יַהֲתִיבוּן. יִנָּתְנוּ:",3,0],[6,5,"וִיהָךְ. יֵלֵךְ כָּל הַמַּעֲשֶׂה הַזֶּה לַהֵיכָל אֲשֶׁר בִּירוּשָׁלַיִם לִמְקוֹמוֹ:",4,0],[6,5,"וְתַחֵת. וַיְהִי מוּנָּח בְּבֵיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",5,0],[6,6,"כְּעַן תַּתְּנַי וְגוֹ׳. זוֹ הִיא תְּשׁוּבָה אֲשֶׁר הֵשִׁיב דָּרְיָוֶשׁ אֶל תַּתְּנַי וּשְׁתַר בּוֹזְנַי:",1,0],[6,6,"דִּי בַּעֲבַר נַהֲרָה. לְצַד אֶרֶץ יִשְׂרָאֵל שֶׁהוּא עֵבֶר הַנָּהָר לְאוֹתָן שֶׁבְּבָבֶל:",2,0],[6,6,"רַחִיקִין הֲווֹ מִן תַּמָּה. רְחוֹקִים תִּהְיוּ מִשָּׁם, מִבִּנְיַן בֵּית הַמִּקְדָּשׁ שֶׁלֹּא תַּרְפּוּ יְדֵי עוֹשֵׂי הַמְּלָאכָה:",3,0],[6,7,"דֵךְ. זֶה:",1,0],[6,7,"פַּחַת יְהוּדָיֵא. שָׁלְטוֹנֵי הַיְּהוּדִים יַעֲשׂוּ דָּבָר זֶה:",2,0],[6,7,"וּלְשָׂבֵי יְהוּדָיֵא. וְלִזְקְנֵי הַיְּהוּדִים אֲנִי מְצַוֶּה:",3,0],[6,7,"בֵּית אֱלָהָא דֵךְ. בֵּית אֱלֹהִים זֶה:",4,0],[6,8,"וּמִנִּי שִׂים טְעֵם. וּמִמֶּנִּי יִהְיֶה צִוּוּי זֶה:",1,0],[6,8,"לְמָא דִי תַעַבְדוּן. לְאוֹתוֹ בִּנְיַן הַמְּלָאכָה אֲשֶׁר תַּעֲשׂוּן עִם זִקְנֵי הַיְּהוּדִים הָאֵלֶּה לִבְנוֹת בֵּיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[6,8,"וּמִנִּכְסֵי מַלְכָּא. מִנִּכְסֵי הַמֶּלֶךְ יִהְיוּ עוֹשִׂים הַבִּנְיָן הַזֶּה:",3,0],[6,8,"דִּי מִדַּת עֲבַר נַהֲרָה. מִן הַמַּס שֶׁל עֵבֶר הַנָּהָר אֲשֶׁר לַמֶּלֶךְ, מִדַּת מַס כְּמוֹ ״מִנְדָּה בְלוֹ וַהֲלָךְ״ (עזרא ד:יג). אָסְפַּרְנָא. מְהֵרָה יִבָּנֶה הַבִּנְיָן. אָסְפַּרְנָה אישפלונטמנ״ט בְּלַעַ״ז:",4,0],[6,8,"נִפְקְתָא תֶּהֱוֵא מִתְיַהֲבָא. הוֹצָאָה תִּהְיֶה נִתֶּנֶת לָאֲנָשִׁים הָאֵלֶּה אֲשֶׁר לֹא יִתְבַּטְּלוּ מִמְּלַאכְתָּן:",5,0],[6,9,"וּמָה חַשְׁחָן. וּמָה שֶׁיִּהְיוּ חוֹשְׁשִׁין:",1,0],[6,9,"וּבְנֵי תוֹרִין. בְּנֵי בָקָר וְאֵילִים וּכְבָשִׂים לְעוֹלוֹת לֵאלֹהֵי הַשָּׁמָיִם:",2,0],[6,9,"וְחִנְטִין. לְסֹלָתוֹת וּמֶלַח לְקָרְבָּנוֹת. וְיַיִן לִנְסָכִים. וְשֶׁמֶן לִמְנָחוֹת, כַּאֲשֶׁר יֹאמְרוּ הַכֹּהֲנִים אֲשֶׁר בִּירוּשָׁלַיִם יְהִי נָתוּן לָהֶם דְּבַר יוֹם בְּיוֹמוֹ:",3,0],[6,9,"דִּי לָא שָׁלוּ. בְּלֹא דִּיחוּי, שנ״ץ דישטורבי״ר בְּלַעַ״ז:",4,0],[6,10,"דִּי לֶהֱוֺן. לְמַעַן אֲשֶׁר יִהְיוּ מַקְרִיבִים נִיחוֹחִים לֵאלֹהֵי הַשָּׁמַיִם וְיִהְיוּ מִתְפַּלְּלִים עַל חַיֵּי הַמֶּלֶךְ וּבָנָיו:",1,0],[6,11,"וּמִנִּי שִׂים טְעֵם. וּמִמֶּנִּי שִׂים צִוּוּי וְשִׂימַת דָּבָר אֲשֶׁר כָּל אָדָם אֲשֶׁר יְשַׁנֶּה דָּבָר זֶה",1,0],[6,11,"יִתְנְסַח. יֵחָרֵב עֵצָיו מִבֵּיתוֹ שֶׁיֵּחָרֵב בֵּיתוֹ, יִתְנְסַח כְּמוֹ ״וְנִסַּחְתֶּם מֵעַל הָאֲדָמָה״ (דברים כח:סג):",2,0],[6,11,"וּזְקִיף יִתְמְחֵא עֲלוֹהִי. וְעֵץ לִתְלוֹתוֹ יְהֵא גָבוֹהַּ עָלָיו שֶׁיִּתָּלֶה עַל הָעֵץ:",3,0],[6,11,"וּבַיְתֵהּ נְוָלוּ יִתְעֲבֵד. וּבֵיתוֹ יֵעָשֶׂה אַשְׁפָּה עַל כָּךְ:",4,0],[6,11,"נְוָלוּ. עִנְיַן טִנּוּף וּמַחֲרָאוֹת:",5,0],[6,12,"וֵאלָהָא דִּי שַׁכִּן שְׁמֵיהּ. וְהָאֱלֹהִים אֲשֶׁר שִׁכֵּן שְׁמוֹ שָׁם:",1,0],[6,12,"יְמַגַּר. יְמַגֵּר וִיפַגֵּר כָּל אוֹתוֹ מֶלֶךְ וְכָל אוֹתוֹ עַם אֲשֶׁר יִשְׁלַח יָדוֹ לְהַחֲרִיב וּלְהַשְׁחִית בֵּיתוֹ זֶה שֶׁל ה׳ אֲשֶׁר בִּירוּשָׁלָיִם:",2,0],[6,12,"שָׂמֶת טְעֵם. שַׂמְתִּי צִוּוּי דָּבָר זֶה אֲשֶׁר יַעֲשֶׂה הַבִּנְיָן מְהֵרָה. עַד כָּאן תְּשׁוּבָתוֹ שֶׁל דָּרְיָוֶשׁ:",3,0],[6,13,"כְּנֵמָא. כַּאֲשֶׁר נֶאֱמַר:",1,0],[6,13,"אָסְפַּרְנָא עֲבַדוּ. מְהֵרָה עֲשׂוּ׃",2,0],[6,14,"וְשָׂבֵי יְהוּדָיֵא. וְזִקְנֵי הַיְּהוּדִים הָיוּ בּוֹנִין וּמַצְלִיחִין בִּמְלַאכְתָּן כִּנְבוּאַת חַגַּי וּזְכַרְיָה, וּבָנוּ וְיִסְּדוּ אֶת הַבִּנְיָן מִן צִוּוּי שֶׁל אֱלֹהֵי יִשְׂרָאֵל וּמֵרְשׁוּת כּוֹרֶשׁ מֶלֶךְ פָּרַס הָרִאשׁוֹן אֲשֶׁר הוּחַל יְסוֹד הַבִּנְיָן בְּיָמָיו, וּמֵרְשׁוּת דָּרְיָוֶשׁ זֶה מֶלֶךְ פָּרַס:",1,0],[6,14,"וְאַרְתַּחְשַׁשְׂתְּא. הוּא דָּרְיָוֶשׁ וְנִקְרָא אַרְתַּחְשַׁשְׂתְּא עַל שֵׁם הַמְּדִינָה וְהַמַּלְכוּת, כִּי כָל מַלְכֵי פָרַס הָיוּ נִקְרָאִים כָּךְ, כַּאֲשֶׁר כָּל מַלְכֵי מִצְרַיִם נִקְרָאִים פַּרְעֹה:",2,0],[6,15,"וְשֵׁיצִיא בַּיְתָה דְנָה. וְסוֹף תַּשְׁלוּם בַּיִת זֶה הָיָה עַד יוֹם שְׁלִישִׁי לְחֹדֶשׁ אֲדָר שֶׁהִיא שְׁנַת שֵׁשׁ לְדָרְיָוֶשׁ הַמֶּלֶךְ, וְנִמְצָא בִּנְיַן הַבַּיִת הָיָה אַרְבַּע שָׁנִים:",1,0],[6,17,"וְהִקְרִיבוּ לַחֲנֻכַּת. הִקְרִיבוּ לַחֲנֻכַּת בַּיִת זֶה קָרְבָּנוֹת הַלָּלוּ, וְהוֹרָאַת שָׁעָה הָיְתָה:",1,0],[6,18,"וַהֲקִימוּ כָהֲנַיָּא בִּפְלֻגָּתְהוֹן. שֶׁהָיוּ הַכֹּהֲנִים חֲלוּקִים בַּעֲבוֹדָתָם וְלֵוִיִּם בְּמִשְׁמְרוֹת:",1,0],[6,19,"אֶת הַפָּסַח. עַכְשָׁיו עָשׂוּ יִשְׂרָאֵל אֶת הַפֶּסַח בְּאַרְבַּעָה עָשָׂר בְּנִיסָן זֶה הַבָּא אַחַר אֲדָר זֶה שֶׁהֻשְׁלַם הַבִּנְיָן בּוֹ:",1,0],[6,20,"וְלָהֶם. וּלְעַצְמָם:",1,0],[6,21,"וְכֹל הַנִּבְדָּל. הֵם הַגֵּרִים שֶׁנִּבְדְּלוּ מִטֻּמְאַת הָעֲבוֹדָה כּוֹכָבִים לִידָּבֵק בְּיִשְׂרָאֵל:",1,0],[6,22,"וְהֵסֵב לֵב מֶלֶךְ אַשּׁוּר עֲלֵיהֶם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵסֵב לֵב מֶלֶךְ אַשּׁוּר עַל יִשְׂרָאֵל הַיּוֹשְׁבִים בְּמֶמְשַׁלְתּוֹ בְּאֶרֶץ אַשּׁוּר לְהַחֲזִיקָם וּלְסַיֵּעַ בִּמְלֶאכֶת הַבִּנְיָן:",1,0],[7,1,"וְאַחַר הַדְּבָרִים הָאֵלֶּה. שֶׁל בִּנְיַן הַבַּיִת:",1,0],[7,1,"אַרְתַּחְשַׁסְתְּא. הוּא דָּרְיָוֶשׁ:",2,0],[7,6,"וַיִּתֶּן לוֹ הַמֶּלֶךְ. דָּרְיָוֶשׁ:",1,0],[7,6,"כְּיַד ה׳ אֱלֹהָיו עָלָיו. כַּאֲשֶׁר צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָיו, וּמִקְרָא מְסֹרָס הוּא: וַיִּתֶּן לוֹ הַמֶּלֶךְ כָּל בַּקָּשָׁתוֹ כְּיַד ה׳ אֱלֹהָיו עָלָיו. וְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה עֶזְרָא הוּא מַלְאָכִי (מגילה טו.):",2,0],[7,7,"בִּשְׁנַת שֶׁבַע. הִיא שָׁנָה אַחַר תַּשְׁלוּם הַבַּיִת:",1,0],[7,7,"לְאַרְתַּחְשַׁסְתְּא. הוּא דָּרְיָוֶשׁ:",2,0],[7,8,"בַּחֹדֶשׁ הַחֲמִישִׁי. הוּא חֹדֶשׁ אָב, כִּי בְּאֶחָד לַחֹדֶשׁ נִיסָן אוֹתוֹ הַיּוֹם הָיְתָה תְּחִלַּת עֲלִיָּתָם מִבָּבֶל, וּבְאֶחָד לְחֹדֶשׁ אָב בָּאוּ לִירוּשָׁלַיִם:",1,0],[7,9,"יְסֻד הַמַּעֲלָה. יְסוֹד תְּחִלַּת הָעֲלִיָּה:",1,0],[7,9,"כְּיַד אֱלֹהָיו. כַּאֲשֶׁר הִצְלִיחוֹ יַד הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיְתָה יָדוֹ טוֹבָה עָלָיו לְהַצְלִיחוֹ בִּדְרָכָיו:",2,0],[7,10,"כִּי עֶזְרָא וְגוֹ׳. וְעַל כֵּן הָלַךְ וְהִצְלִיחַ בְּדַרְכּוֹ, שֶׁהֲרֵי עֶזְרָא הֵכִין לְבָבוֹ וְגוֹמֵר, נוֹתֵן טַעַם לִדְבָרָיו:",1,0],[7,11,"וְזֶה פַּרְשֶׁגֶן הַנִּשְׁתְּוָן. וְזֶה פַּתְשֶׁגֶן הַכְּתָב:",1,0],[7,11,"וְחֻקָּיו עַל יִשְׂרָאֵל. וְאֶת חֻקָּיו אֲשֶׁר צִוָּה עַל יִשְׂרָאֵל לְשָׁמְרָם:",2,0],[7,12,"סָפַר דָּתָא. סֵפֶר תּוֹרָה:",1,0],[7,12,"גְּמִיר וּכְעֶנֶת. סְפֵיקָא הִיא בְּיָדוֹ:",2,0],[7,13,"מִנִּי שִׂים טְעֵם. מִמֶּנִּי יוֹצֵא הָרְשׁוּת כִּי כָּל אֲשֶׁר נָדְבָה רוּחוֹ אוֹתוֹ מִן יִשְׂרָאֵל מִן הַכֹּהֲנִים וְהַלְוִיִּם לָלֶכֶת לִירוּשָׁלַיִם יֵלְכוּ עִמָּךְ:",1,0],[7,14,"כָּל קֳבֵל. בִּשְׁבִיל כָּךְ מֵאֵת הַמֶּלֶךְ וְשִׁבְעַת יוֹעֲצָיו רוֹאֵי פְנֵי הַמֶּלֶךְ אַתָּה שָׁלוּחַ:",1,0],[7,14,"וְשִׁבְעַת יָעֲטוֹהִי. וְשֶׁבַע יוֹעֲצָיו הֵם שִׁבְעָה רוֹאֵי פְּנֵי הַמֶּלֶךְ (אסתר א:יד):",2,0],[7,14,"לְבַקָּרָה עַל יְהוּד. כְּדֵי לִדְרֹשׁ וְלִבְדֹּק עַל הַיְּהוּדִים אֲשֶׁר בִּירוּשָׁלַיִם אִם הֵם עֲסוּקִים בְּתוֹרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר בְּיָדְךָ:",3,0],[7,15,"וּלְהֵיבָלָה. וּלְהוֹלִיךְ כֶּסֶף וְזָהָב שֶׁל הַמֶּלֶךְ וְיוֹעֲצָיו אֲשֶׁר הִתְנַדֵּב לֵאלֹהֵי יִשְׂרָאֵל לְתַקֵּן בֵּיתוֹ אֲשֶׁר מִשְׁכָּנוֹ וּבֵיתוֹ בִּירוּשָׁלָיִם:",1,0],[7,16,"וְכָל כְּסַף וּדְהַב. וְכָל נִדְבַת כֶּסֶף וְזָהָב אֲשֶׁר תִּמְצָא בִּמְדִינַת בָּבֶל עִם שְׁאָר נִדְבַת הָעָם וְהַכֹּהֲנִים אֲשֶׁר מִתְנַדְּבִים לְבֵיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר בִּירוּשָׁלַיִם, תּוֹלִיךְ הַכֹּל לִירוּשָׁלָיִם:",1,0],[7,17,"כָּל קֳבֵל דְּנָה. וּבִשְׁבִיל כָּךְ שֶׁל עֲבוֹדוֹת הַמִּקְדָּשׁ מְהֵרָה תִּקְנֶה בְּכֶסֶף זֶה בָּקָר וְאֵילִים וּכְבָשִׂים וּזְבָחִים וּמְנָחוֹת וּנְסָכִים, וְתַקְרִיבֵם עַל הַמִּזְבֵּחַ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[7,18,"וּמָה דִי עֲלָךְ. וַאֲשֶׁר יִיטַב לְךָ וּלְאַחֶיךָ בְּמוֹתַר הַכֶּסֶף וְהַזָּהָב לַעֲשׂוֹת כִּרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא תַּעֲשׂוּ:",1,0],[7,19,"וּמָאנַיָּא. וְכֵלִים הַנְּתוּנִים לְךָ לַעֲבוֹדָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁלֵם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּירוּשָׁלַיִם:",1,0],[7,20,"וּשְׁאָר חַשְׁחוּת. וּשְׁאָר צְרִיכוּת שֶׁתִּצְטָרֵךְ לְבֵיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לִקְנוֹת, אֲשֶׁר יִהְיֶה לְךָ לִיתֵּן הַדָּמִים תִּתֵּן מֵאוֹצַר הַמֶּלֶךְ:",1,0],[7,21,"וּמִנִּי אֲנָה. וּמִמֶּנִּי אֲנִי דָּרְיָוֶשׁ הַמֶּלֶךְ יוֹצֵא צִוּוּי וְרָשׁוּת לְכָל הַגִּזְבָּרִים אֲשֶׁר בְּעֵבֶר הַנָּהָר לְצַד אֶרֶץ יִשְׂרָאֵל הַמְקַבְּלִים מִסִּים שֶׁלִּי מִן הָעוֹבְדֵי כוֹכָבִים אֲשֶׁר כָּל דָּבָר שֶׁיִּשְׁאַל מִכֶּם עֶזְרָא הַכֹּהֵן סוֹפֵר הַתּוֹרָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מְהֵרָה יֵעָשֶׂה שֶׁלֹּא יְעַכְּבוּ אֶת שְׁאֵלָתוֹ עַד מֵאָה כִּכָּרִים שֶׁל כֶּסֶף לִקְנוֹת קָרְבָּנוֹת וּמֵאָה כוֹרִין חִטִּין לִמְנָחוֹת וְעַד מֵאָה מִדּוֹת יַיִן לִנְסָכִים וּמֵאָה (מִדּוֹת) שֶׁל שֶׁמֶן לִבְלוֹל מְנָחוֹת וּמֶלַח לְקָרְבָּנוֹת כְּעִנְיָן שֶׁנֶּאֱמַר ״וְכָל קָרְבַּן מִנְחָתְךָ בַּמֶּלַח תִּמְלָח״ (ויקרא ב:יג):",1,0],[7,22,"דִּי לָא כְתָב. וּמֶלַח שֶׁאֵין כָּתוּב בּוֹ מִדָּה יִתְּנוּ כְּכָל הַצֹּרֶךְ:",1,0],[7,23,"כָּל דִּי מִן טַעַם. כָּל אֲשֶׁר יִהְיֶה מֵרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְצִוּוּיוֹ יֵעָשֶׂה בִּזְרִיזוּת בְּחוֹתַם הַמֶּלֶךְ לְבֵיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[7,23,"אַדְרַזְדָּא. חוֹתָם בִּלְשׁוֹן עֲרָבִי:",2,0],[7,23,"דִּי לְמָה לֶהֱוֵא. אֲשֶׁר לָמָּה יִהְיֶה קֶצֶף עַל מַלְכוּת הַמֶּלֶךְ וּבָנָיו, וְעַל כֵּן יִתְּנוּ הַגִּזְבָּרִים כָּל צָרְכֵי הַבַּיִת:",3,0],[7,24,"וּלְכוֹם מְהוֹדְעִין. וּלְכֶם אָנוּ מוֹדִיעִים אֲשֶׁר כָּל הַכֹּהֲנִים וְהַלְוִיִּם הַמְשׁוֹרְרִים וְהַשּׁוֹעֲרִים וְהַנְּתִינִים שֶׁהֵם חוֹטְבֵי עֵצִים וְשׁוֹאֲבֵי מַיִם לַמִּזְבֵּחַ וְעוֹבְדִים בְּבַיִת זֶה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא יִשְׁלוֹט אָדָם עֲלֵיהֶם לְהַשְׁלִיךְ עֲלֵיהֶם מַס וְכֶסֶף גֻּלְגֹּלֶת, אֶלָּא יִהְיוּ בְּנֵי חוֹרִין מֵעֲבוֹדַת הַמֶּלֶךְ:",1,0],[7,25,"וְאַנְתְּ עֶזְרָא כְּחָכְמַת אֱלָהָךְ דִּי בִידָךְ. וְאַתָּה עֶזְרָא כְּפִי חָכְמַת אֱלֹהֶיךָ אֲשֶׁר בְּיָדֶיךָ יוֹתֵר מִן הַשּׁוֹפְטִים וְהַדַּיָּנִים שֶׁהֵם דָּנִין כָּל הָעָם שֶׁבְּעֵבֶר הַנָּהָר לְצַד אֶרֶץ יִשְׂרָאֵל עִם יוֹדְעֵי הַתּוֹרָה:",1,0],[7,25,"וְדִי לָא יָדַע. וְהַשּׁוֹפֵט אֲשֶׁר לֹא יָדַע לִשְׁפּוֹט, תּוֹדִיעַ לוֹ הַמִּשְׁפָּט לַעֲשׂוֹתוֹ:",2,0],[7,26,"וְכָל דִּי לָא לֶהֱוֵא עָבֵד. וְכָל אֲשֶׁר לֹא יִהְיֶה עוֹשֶׂה דָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְדַת הַמֶּלֶךְ, מְהֵרָה יְעֻכַּב הַדִּין וְהַמִּשְׁפָּט:",1,0],[7,26,"דִּינָה. הַדִּין יֵעָשֶׂה מִמֶּנּוּ מִן הַמְעַכֵּב מִשְׁפָּט:",2,0],[7,26,"הֵן לָמוּת. לַהֲרֹג:",3,0],[7,26,"הֵן לִשְׁרוֹשִׁי. אִם לְעָקְרוֹ מִן הָעוֹלָם אוֹתוֹ וְאֶת זַרְעוֹ וְאֶת מִשְׁפַּחְתּוֹ, לִשְׁרוֹשִׁי דישראצינ״ר בְּלַעַ״ז:",4,0],[7,26,"הֵן לַעֲנָשׁ נִכְסִין. אִם לְעָנְשׁוֹ בְּמָמוֹן:",5,0],[7,26,"וְלֶאֱסוּרִין. אוֹ לְיַסְּרוֹ בְּיִסּוּרִין. עַד כָּאן מִכְתַּב הָאִגֶּרֶת אֲשֶׁר נָתַן דָּרְיָוֶשׁ הַמֶּלֶךְ לְעֶזְרָא הַסּוֹפֵר לְמַעַן יִשָּׂאֵהוּ לִירוּשָׁלַיִם לְהַרְאוֹתוֹ אֶל הַכֹּהֲנִים וְהַלְוִיִּם וְגִזְבָּרֵי הַמֶּלֶךְ, לְמַעַן יַחֲזִיקוּ לְקַיֵּם הַמִּצְוֹת וְלַעֲבֹד ה׳ בְּבֵית הַמִּקְדָּשׁ וְלִשְׁמֹר הַתּוֹרָה כַּמִּשְׁפָּט:",6,0],[7,27,"בָּרוּךְ ה׳. כָּךְ כָּתַב עֶזְרָא בְּסִפְרוֹ כַּאֲשֶׁר נָתַן הוֹדָאָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[7,28,"וְיוֹעֲצָיו. הֵם שִׁבְעָה רוֹאֵי פְנֵי הַמֶּלֶךְ, הֵן שִׁבְעָה יְעָטוּהִי שֶׁל מַעְלָה:",1,0],[7,28,"כְּיַד ה׳ אֱלֹהַי עָלַי. כַּאֲשֶׁר הָיְתָה עֶזְרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עָלַי, וְקִבַּצְתִּי מִיִּשְׂרָאֵל הַנִּשְׁאָרִים בְּבָבֶל רָאשֵׁי אָבוֹת וּגְדוֹלִים לַעֲלוֹת עִמִּי מִבָּבֶל:",2,0],[8,1,"וְאֵלֶּה רָאשֵׁי אֲבוֹתֵיהֶם. שֶׁל עוֹלִים:",1,0],[8,1,"וְהִתְיַחְשָׂם. אֶת יִחוּסָם אֲשֶׁר הָיוּ מִתְיַחֲשִׂים בָּהֶם:",2,0],[8,1,"אַרְתַּחְשַׁסְתְּא. הוּא דָּרְיָוֶשׁ:",3,0],[8,3,"מִבְּנֵי שְׁכַנְיָה מִבְּנֵי פַרְעֹשׁ. מִשְׁפָּחָה אַחַת הִיא, וְזְכַרְיָה הוּא רֹאשׁ הַמִּשְׁפָּחָה:",1,0],[8,3,"וְעִמּוֹ. וְעִם יַחַס שֶׁלּוֹ הָיוּ מִתְיַחֲסִים הַזְּכָרִים שֶׁל מִשְׁפַּחְתּוֹ:",2,0],[8,6,"עֶבֶד בֶּן יוֹנָתָן. כָּךְ שְׁמוֹ:",1,0],[8,13,"אַחֲרוֹנִים. שֶׁהָיוּ אַחֲרוֹנִים לָלֶכֶת אַחֲרֵי עֶזְרָא:",1,0],[8,15,"אֶל הַנָּהָר הַבָּא. אֶל הַנָּהָר הַנּוֹבֵעַ:",1,0],[8,15,"אֶל אַהֲוָא. אֶל אוֹתוֹ הַנָּהָר:",2,0],[8,15,"וְנַחֲנֶה שָׁם. וְהָיִינוּ חוֹנִים שָׁם:",3,0],[8,15,"וָאָבִינָה בָעָם. נָתַתִּי לִבִּי לְהָבִין בָּעָם אֲשֶׁר נִקְבְּצוּ עִמִּי:",4,0],[8,16,"וָאֶשְׁלְחָה לֶאֱלִיעֶזֶר וְגוֹ׳. רָאשִׁים, גְּדוֹלִים:",1,0],[8,16,"מְבִינִים. חֲכָמִים הָיוּ:",2,0],[8,17,"וָאֲצַוֶּה אוֹתָם וְגוֹ׳. שְׁלַחְתִּים וְצִוִּיתִים לְדַבֵּר אֶל אִדּוֹ שֶׁהוּא גָּדוֹל וְחָשׁוּב אֲשֶׁר בְּכָסִפְיָא:",1,0],[8,17,"עַל אִדּוֹ. אֶל אִדּוֹ:",2,0],[8,17,"וָאָשִׂימָה בְּפִיהֶם. שַׂמְתִּי בְּפִיהֶם דְּבָרִים לְדַבֵּר בִּשְׁלִיחוּתִי אֶל אִדּוֹ וְאֶחָיו שֶׁהֵם נְתוּנִים וּמְיֻשָּׁבִים בְּכָסִפְיָא לְהָבִיא לָנוּ מְשָׁרְתִים לַעֲבֹד בְּבֵית הַמִּקְדָּשׁ:",3,0],[8,17,"בְּכָסִפְיָא. שֵׁם מָקוֹם בְּבָבֶל:",4,0],[8,17,"אֶל אִדּוֹ אָחִיו. שֵׁם אָדָם:",5,0],[8,17,"הַנְּתוּנִים. כְּמוֹ הַנְּתִינִים, וְעַל כֵּן נִכְתַּב בְּוָי״ו:",6,0],[8,18,"כְּיַד אֱלֹהֵינוּ. כַּאֲשֶׁר הָיְתָה הַצְלָחָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עָלֵינוּ:",1,0],[8,18,"אִישׁ שֶׂכֶל. חָכָם:",2,0],[8,18,"מִבְּנֵי מַחְלִי וְגוֹ׳. כֻּלָּם הַלָּלוּ לְוִיִּם:",3,0],[8,20,"וּמִן הַנְּתִינִים. וּמִן הָעֲבָדִים נְתִינִים שֶׁנָּתַן דָּוִד הַמֶּלֶךְ וְשָׂרֵי יִשְׂרָאֵל עָלוּ עִמָּהֶם:",1,0],[8,21,"לְהִתְעַנּוֹת. לֵישֵׁב בְּתַעֲנִית:",1,0],[8,21,"דֶּרֶךְ יְשָׁרָה. שֶׁיּוֹלִיכֵנִי הַמָּקוֹם לְשָׁלוֹם:",2,0],[8,22,"כִּי בֹשְׁתִּי. שֶׁהֲרֵי נִתְבַּיַּשְׁתִּי מִן הַמֶּלֶךְ שֶׁלֹּא רָצִיתִי לִשְׁאֹל לוֹ רֶכֶב וּפָרָשִׁים כְּדֵי לְתַיְּרֵנוּ:",1,0],[8,22,"כִּי אָמַרְנוּ. שֶׁהֲרֵי כְּבָר אָמַרְנוּ אֶל דָּרְיָוֶשׁ הַמֶּלֶךְ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵטִיב לִמְבַקְשָׁיו וְשׁוֹפֵךְ אַפּוֹ וַחֲמָתוֹ עַל עוֹזְבָיו:",2,0],[8,23,"וַיֵּעָתֵר לָנוּ. וְקִבֵּל תְּפִלָּתֵינוּ שֶׁבָּאנוּ לִירוּשָׁלַיִם לְשָׁלוֹם:",1,0],[8,24,"וָאַבְדִּילָה. וְכַאֲשֶׁר הָיִיתִי שָׁם עַל נְהַר אַהֲוָא הִבְדַּלְתִּי מִשָּׂרֵי הַכֹּהֲנִים וְשָׁקַלְתִּי לָהֶם הַכֶּסֶף וְהַזָּהָב לִיתֵּן בְּאוֹצְרוֹת בֵּית ה׳:",1,0],[8,25,"הַהֵרִימוּ. אֲשֶׁר הֵרִימוּ הַנִּמְצָאִים בְּבָבֶל:",1,0],[8,26,"וּכְלֵי כֶסֶף מֵאָה לַכִּכָּרִים. כִּכָּר בְּכָל כְּלִי:",1,0],[8,27,"וּכְפוֹרֵי. מִזְרָקִים:",1,0],[8,27,"לַאֲדַרְכֹּנִים אָלֶף. מִין מַטְבֵּעַ, אֶלֶף דַּרְכּוֹנִים הָיוּ בְּעֶשְׂרִים כְּפֹרֵי זָהָב הַלָּלוּ:",2,0],[8,27,"מֻצְהָב. מִשֶּׁל נְחֹשֶׁת מֻצְהָב, (אוֹ) מִין מַטְבֵּעַ שֶׁל נְחֹשֶׁת:",3,0],[8,27,"טוֹבָה. לְשׁוֹן נְקֵבָה קוֹרֵא לַנְּחֹשֶׁת:",4,0],[8,27,"שְׁנַיִם. שְׁנֵי כֵלִים:",5,0],[8,27,"חֲמוּדוֹת כַּזָּהָב. הַכֵּלִים קוֹרֵא חֲמוּדוֹת בִּלְשׁוֹן נְקֵבָה:",6,0],[8,28,"אֲלֵיהֶם. לְאוֹתָן שָׂרֵי הַכֹּהֲנִים:",1,0],[8,29,"הַלִּשְׁכוֹת בֵּית ה׳. כְּדֵי לִיתֵּן בַּלִּשְׁכוֹת הַבַּיִת:",1,0],[8,31,"בִּשְׁנֵים עָשָׂר לַחֹדֶשׁ הָרִאשׁוֹן. בִּשְׁנֵים עָשָׂר לְנִיסָן:",1,0],[8,31,"וְיַד אֱלֹהֵינוּ הָיְתָה עָלֵינוּ. לְהַצְלִיחֵנוּ עַל הַדֶּרֶךְ אֲשֶׁר הָלַכְנוּ עָלֶיהָ:",2,0],[8,34,"בְּמִסְפָּר בְּמִשְׁקָל לַכֹּל. מִסְפַּר הַכֵּלִים וּמִשְׁקָלָם כַּאֲשֶׁר קִבְּלוּהוּ כָּךְ הָיָה נִשְׁקָל כֻּלּוֹ כַּאֲשֶׁר פְּרָעוּהוּ:",1,0],[8,35,"הַבָּאִים מֵהַשְּׁבִי בְּנֵי הַגּוֹלָה. הַלָּלוּ אֲשֶׁר בָּאוּ עִם עֶזְרָא:",1,0],[8,35,"הִקְרִיבוּ עוֹלוֹת. הַכֹּל עוֹלָה, וְהוֹרָאַת שָׁעָה הָיְתָה:",2,0],[8,36,"וַיִּתְּנוּ אֶת דָּתֵי הַמֶּלֶךְ. הַלָּלוּ עוֹלֵי גוֹלָה סִפְּרוּ מִצְוַת דָּרְיָוֶשׁ הַמֶּלֶךְ לִגְדוֹלֵי הַמֶּלֶךְ רוֹאֵי פָנָיו:",1,0],[8,36,"וּפַחֲווֹת. כְּמוֹ וּפַחוֹת:",2,0],[8,36,"עֵבֶר הַנָּהָר. אוֹתָן שֶׁל צַד אֶרֶץ יִשְׂרָאֵל הֵן בְּעֵבֶר הַנָּהָר לְיוֹשְׁבֵי בָּבֶל:",3,0],[8,36,"וְנִשְּׂאוּ. שֶׁהָיוּ מְנַשְּׂאִין וּמְסַיְּעִין:",4,0],[9,1,"אֵלֶּה. דְּבָרִים הַלָּלוּ אֲשֶׁר סִפְּרוּ דָּתֵי הַמֶּלֶךְ:",1,0],[9,1,"וְהַשָּׂרִים. שֶׁל יִשְׂרָאֵל:",2,0],[9,1,"לֵאמֹר. וְכֵן אָמְרוּ לִי:",3,0],[9,2,"הָיְתָה בַּמַּעַל הַזֶּה רִאשׁוֹנָה. שֶׁהֵם הִתְחִילוּ לִמְעוֹל מַעַל לְהִתְחַתֵּן בְּגוֹיֵי הָאֲרָצוֹת:",1,0],[9,3,"מְשׁוֹמֵם. עָלוּב וְשׁוֹמֵם, כְּמוֹ (יחזקאל ג:טו) ״שִׁבְעַת יָמִים מַשְׁמִים בְּתוֹכָם״:",1,0],[9,5,"מִתַּעֲנִיתִי. שֶׁלֹּא אָכַלְתִּי אוֹתוֹ יוֹם:",1,0],[9,7,"נִתַּנּוּ. כְּמוֹ נְתַנְנוּ, דָּגֵשׁ הַנּוּ״ן תַּחַת חֶסְרוֹן נוּ״ן אַחֶרֶת, כְּמוֹ ״כִּי עָלֶיךָ תִשְּׁעַנוּ״ (דברי הימים ב יד:יד) כְּמוֹ נִשְׁעַנְנוּ, ״וְנָתַנּוּ אֶת בְּנֹתֵינוּ״ (בראשית לד:טז) כְּמוֹ וְנָתַנְנוּ:",1,0],[9,7,"כְּהַיּוֹם הַזֶּה. כְּמוֹ שֶׁנִּרְאֶה הַיּוֹם הַזֶּה, שֶׁכְּבָר גָּלוּ עֲשֶׂרֶת הַשְּׁבָטִים וַעֲדַיִן נִשְׁאֲרוּ בְּבָבֶל הַרְבֵּה מִן הַגּוֹלִים:",2,0],[9,8,"וְעַתָּה כִּמְעַט רֶגַע. לְפִי שָׁעָה:",1,0],[9,8,"תְּחִנָּה. כְּמוֹ חֲנִינָה:",2,0],[9,8,"וְלָתֶת לָנוּ יָתֵד. לִקְבֹּעַ אוֹתָנוּ בְּאֶרֶץ יִשְׂרָאֵל:",3,0],[9,8,"יָתֵד. כְּמוֹ (ישעיהו כב:כג) ״וּתְקַעְתִּיו יָתֵד בְּמָקוֹם נֶאֱמָן״:",4,0],[9,8,"מְחְיָה מְעַט. חַיִּים מוּעָטִים:",5,0],[9,9,"כִּי עֲבָדִים אֲנַחְנוּ. לְדָרְיָוֶשׁ מֶלֶךְ פָּרָס:",1,0],[9,9,"לֹא עֲזָבָנוּ. לֹא עָזַב אוֹתָנוּ:",2,0],[9,9,"וַיַּט. לְשׁוֹן מִפְעָל כְּמוֹ ״מַטֶּה״, הַטֵּה עָלֵינוּ חַסְדּוֹ:",3,0],[9,9,"גָּדֵר. שֶׁהָיוּ גּוֹדְרִין גָּדֵר לִשְׁמֹר מִצְוֹתָיו:",4,0],[9,11,"נִדָּה. טְמֵאָה וּגְעוּלָה:",1,0],[9,12,"וְהוֹרַשְׁתֶּם. אֶת הָאָרֶץ לִבְנֵיכֶם עַד עוֹלָם:",1,0],[9,13,"וְאַחֲרֵי כָּל הַבָּא עָלֵינוּ. אַחֲרֵי כָּל הַמַּעֲשֶׂה הָרָע אֲשֶׁר הִגִּיעַ עָלֵינוּ בְּמַעֲשֵׂינוּ הָרָעִים:",1,0],[9,13,"חָשַׂכְתָּ לְמַטָּה מֵעֲוֺנֵנוּ. מָנַעְתָּ מֵעֲוֺנוֹתֵינוּ עַד לְמַטָּה שֶׁנִּפְחַת עֲוֺנֵינוּ עַל כַּפָּרַת גָּלוּתֵנוּ. וְיֵשׁ לָנוּ לְפוֹתְרוֹ בְּעִנְיָן זֶה: מָנַעְתָּ עַצְמְךָ מִלִּגְבּוֹת מִמֶּנּוּ כָּל עֲוֺנֵינוּ, וְגָבִיתָ מִמֶּנּוּ לְמַטָּה מִן הָעֲוֺנוֹת, וְלֹא פָרַעְתָּ מִמֶּנּוּ כְּכָל חַטֹּאתֵינוּ:",2,0],[9,14,"הֲנָשׁוּב. אִם נָשׁוּב:",1,0],[9,14,"הֲלֹא תֶאֱנַף בָּנוּ. תְּמִיהָה הַמִּתְקַיֶּמֶת:",2,0],[9,15,"כִּי אֵין. כֹּחַ מַעֲשִׂים טוֹבִים בָּנוּ לַעֲמֹד וּלְהִתְקַיֵּם לְפָנֶיךָ עַל עֲבֵירָה זוֹ:",1,0],[10,1,"בֶכֶה. כְּמוֹ בֶּכִי:",1,0],[10,2,"וַנֹּשֶׁב. וְהוֹשַׁבְנוּם:",1,0],[10,2,"יֵשׁ מִקְוֶה. יֵשׁ תִּקְוָה לְיִשְׂרָאֵל עַל כָּךְ שֶׁהֵם יְכוֹלִים לְהוֹצִיא נְשֵׁיהֶם הָעוֹבְדוֹת כּוֹכָבִים וּמַזָּלוֹת וְהַנּוֹלָד מֵהֶם וּלְהוֹצִיא כָּל הַבָּנִים הַנּוֹלָדִים מִן הַנָּשִׁים הָעוֹבְדוֹת כּוֹכָבִים וּמַזָּלוֹת:",2,0],[10,3,"בַּעֲצַת אֲדֹנָי. בַּעֲצָתוֹ וּבִרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[10,3,"וַחֲרֵדִים בְּמִצְוַת אֱלֹהֵינוּ. וְיִרְאֵי שָׁמַיִם יוֹצִיאֵם:",2,0],[10,3,"וְכַתּוֹרָה יֵעָשֶׂה. הָעוֹשֶׂה הַמַּעֲשֶׂה הַזֶּה אֲשֶׁר יוֹצִיא אִשְׁתּוֹ וּבָנָיו הָעוֹבְדֵי כוֹכָבִים:",3,0],[10,4,"וַאֲנַחְנוּ עִמָּךְ. לִהְיוֹת מַסְכִּימִים עִמָּךְ:",1,0],[10,7,"קוֹל. כָּרוֹז:",1,0],[10,8,"לִשְׁלֹשֶׁת הַיָּמִים. לְסוֹף שְׁלֹשֶׁת הַיָּמִים:",1,0],[10,9,"חֹדֶשׁ הַתְּשִׁיעִי. הוּא חֹדֶשׁ כִּסְלֵו:",1,0],[10,9,"מַרְעִידִים עַל הַדָּבָר. מִתְיָרְאִים עַל הַדָּבָר וּמִתְיָרְאִים הָיוּ מִמִּכְשׁוֹל שֶׁל עֲבֵרָה זֹאת:",2,0],[10,9,"וּמֵהַגְּשָׁמִים. וּמִן הַגְּשָׁמִים הַיּוֹרְדִים עֲלֵיהֶם שָׁם הָיוּ רְעוּדִים וַעֲלוּבִים:",3,0],[10,11,"תּוֹדָה. וִדּוּי:",1,0],[10,13,"וְהָעֵת גְּשָׁמִים. שֶׁהַגְּשָׁמִים יוֹרְדִים עָלֵינוּ:",1,0],[10,13,"וְהַמְּלָאכָה. וְהַרְחָקַת עֲבֵרָה זוֹ אֵין אַתָּה יָכוֹל לְתַקֵּן כָּל כָּךְ בִּמְהִירוּת:",2,0],[10,14,"לְכָל הַקָּהָל. עִם כָּל הַקָּהָל:",1,0],[10,14,"הַהוֹשִׁיב. אֲשֶׁר הוֹשִׁיב:",2,0],[10,14,"עַד לְהָשִׁיב. עַד אֲשֶׁר יָשׁוּב חֲרוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מֵעָלֵינוּ:",3,0],[10,15,"עָמְדוּ עַל זֹאת. לְקַנְתֵּר עַל דָּבָר זֶה:",1,0],[10,15,"עֲזָרוּם. הֶחֱזִיקוּ יְדֵיהֶם:",2,0],[10,16,"לְדַרְיוֹשׁ. כְּמוֹ לִדְרוֹשׁ:",1,0],[10,17,"וַיְכַלּוּ בַכֹּל. וְהִשְׁלִימוּ אֶת תִּקּוּן הַמַּעֲשֶׂה מִן הָאֲנָשִׁים אֲשֶׁר הוֹשִׁיבוּ נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים כִּי הוֹצִיאָם:",1,0],[10,17,"לַחֹדֶשׁ הָרִאשׁוֹן. עַד יוֹם אֶחָד בְּנִיסָן:",2,0],[10,19,"יָדָם. עֲצָתָם, כְּמוֹ ״הֲיַד יוֹאָב אִתָּךְ בְּכָל זֹאת״ (שמואל ב יד:יט):",1,0],[10,19,"עַל אַשְׁמָתָם. הוֹרָאַת שָׁעָה הָיְתָה:",2,0],[10,20,"וּמִבְּנֵי אִמֵּר. כָּל אֵלּוּ כֹּהֲנִים עַד וּמִן הַלְוִיִּם וְגוֹמֵר:",1,0],[10,44,"וְיֵשׁ מֵהֶם נָשִׁים וַיָּשִׂימוּ בָנִים. מִקְצָתָן שֶׁהָיוּ לָהֶם נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים שֶׁנּוֹלְדוּ לָהֶם מֵהֶם בָּנִים, וְהַכֹּל הוֹצִיאוּ הַנָּשִׁים וְהַבָּנִים:",1,0]]);
